    if(newForm.elements?.title && currentTitle) newForm.elements.title.value = currentTitle;
    setToast('Seçilen kapak, çıkış tarihi ve tür bilgisi forma işlendi. Kayıt için Kaydet/Güncelle butonuna bas.');
