async function ho240f51StableSave(form){
  if(!form) return setToast('Oyun formu bulunamadı.');
  const isEdit = form.id === 'gameEditForm' || !!form.closest?.('.ho240f47ModalBackdrop,.ho240f49ModalBackdrop') || !!state.editingGameId;
  const draft = ho240f51ReadGame(form);
  if(!draft.title) return setToast('Oyun adı gerekli.');
  ho240f51ActiveSaveButton(form, true);
  try{
    if(isEdit){
      const id = state.editingGameId || form.dataset.gameId || '';
      const current = (state.games || []).find(g=>String(g.id)===String(id));
      if(!current) { setToast('Düzenlenecek oyun bulunamadı.'); return; }
      const patch = { ...current, ...draft, id:current.id };
      state.games = (state.games || []).map(g=>String(g.id)===String(current.id) ? patch : g);
      ho240f51PersistLocalGames();
      setToast('Oyun düzenleme formu kaydedildi. Supabase güncelleniyor...');
      try{
        const res = await api('games-update', { adminToken:state.session?.adminToken, gameId:current.id, game:patch });
        if(res?.game){ const mapped = typeof mapGame === 'function' ? mapGame(res.game) : res.game; state.games = state.games.map(g=>String(g.id)===String(current.id) ? mapped : g); ho240f51PersistLocalGames(); }
        setToast('Oyun Supabase üzerinde güncellendi. Form kapanmadan düzenlemeye devam edebilirsin.');
      }catch(err){ setToast('Oyun local kaydedildi; Supabase güncelleme başarısız: ' + (err?.message || err)); }
    }else{
      const id = draft.id || `local-${Date.now()}`;
      const game = { ...draft, id };
      state.games = [game, ...(state.games || [])];
      state.gameDraft = { ...DEFAULT_GAME_DRAFT };
      ho240f51PersistLocalGames();
      setToast('Yeni oyun local kaydedildi. Supabase kaydı deneniyor...');
      try{
        const res = await api('games-add', { adminToken:state.session?.adminToken, game });
        if(res?.game){ const mapped = typeof mapGame === 'function' ? mapGame(res.game) : res.game; state.games = state.games.map(g=>String(g.id)===String(id) ? mapped : g); ho240f51PersistLocalGames(); }
        setToast('Yeni oyun Supabase games tablosuna kaydedildi.');
        try{ form.reset(); ho240f51Patch(form, { ...DEFAULT_GAME_DRAFT }); }catch{}
      }catch(err){ setToast('Yeni oyun local kaydedildi; Supabase kaydı başarısız: ' + (err?.message || err)); }
    }
  }finally{
    ho240f51ActiveSaveButton(form, false);
  }
}
