function ho240f52Capture(form){
  if(!ho240f52IsGameForm(form)) return;
  const data = ho240f52Read(form);
  const id = form.dataset?.gameId || state.editingGameId || state.ho240f47EditModalId || data.id || '';
  try{
    if(form.id === 'gameEditForm' || form.closest?.('.ho240f47ModalBackdrop,.ho240f49ModalBackdrop')){
      state.editGameDraftSnapshots = state.editGameDraftSnapshots || {};
      const key = String(id || state.editingGameId || state.ho240f47EditModalId || 'modal');
      state.editGameDraftSnapshots[key] = { ...(state.editGameDraftSnapshots[key] || {}), ...data, id:key === 'modal' ? data.id : key };
    }else{
      state.gameDraft = { ...DEFAULT_GAME_DRAFT, ...(state.gameDraft || {}), ...data };
    }
  }catch(error){ console.warn('FIX52 form yakalama atlandı:', error); }
}
function ho240f52Patch(form, patch={}){
  if(!ho240f52IsGameForm(form)) return;
  const lockedTitle = String(form.elements?.title?.value || '').trim();
  Object.entries(patch || {}).forEach(([key,value])=>{
    const el = form.elements?.[key];
    if(!el || value === undefined || value === null) return;
    if(key === 'title' && lockedTitle) return;
    el.value = String(value ?? '');
    el.dispatchEvent(new Event('input', { bubbles:true }));
  });
  if(lockedTitle && form.elements?.title) form.elements.title.value = lockedTitle;
  const cover = String(form.elements?.cover?.value || '').trim();
  form.querySelectorAll('.coverPreview,.fix6PreviewCover,.ho240f46Preview .fix6PreviewCover').forEach(box=>{
    if(box.classList.contains('fix6PreviewCover')){
      const img = box.querySelector('img'); if(img && cover) img.src = cover;
    }else{
      box.classList.toggle('isEmpty', !cover);
      if(cover) box.innerHTML = `<img src="${esc(cover)}" alt="Kapak önizleme">`;
    }
  });
  ho240f52Capture(form);
}
