const HO240F58_PUBLIC_VERSION = 'v2.4.1';
window.__HO240F58_LAST_STEAM__ = window.__HO240F58_LAST_STEAM__ || null;
function ho240f58Norm(value=''){
  return String(value || '')
    .toLocaleLowerCase('tr-TR')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[’'`´]/g,'')
    .replace(/&/g,' and ')
    .replace(/[^a-z0-9ğüşöçıİĞÜŞÖÇ]+/gi,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function ho240f58Date(value=''){
  const raw = String(value || '').trim();
  if(!raw) return '';
  if(/^\d{2}\.\d{2}\.\d{4}$/.test(raw)) return raw;
  const iso = raw.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if(iso) return `${iso[3].padStart(2,'0')}.${iso[2].padStart(2,'0')}.${iso[1]}`;
  const tr = raw.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if(tr) return `${tr[1].padStart(2,'0')}.${tr[2].padStart(2,'0')}.${tr[3]}`;
  return raw;
}
function ho240f58VideoTotals(games=state.games){
  games = Array.isArray(games) ? games : [];
  const totalVideos = games.reduce((a,g)=>a+Number(g.eps || normalizeEpisodes(g.episodes).length || (g.videoUrl?1:0) || 0),0);
  const watchedVideos = games.reduce((a,g)=>a+Number(g.watchedEps || normalizeEpisodes(g.episodes).filter(ep=>ep.watched).length || 0),0);
  const completed = games.filter(g=>String(g.status||'')==='Tamamlandı' || progressPercent(g)>=100).length;
  const missing = games.filter(g=>!String(g.cover||'').trim() || !String(g.releaseDate||'').trim()).length;
  return { totalGames:games.length, totalSeries:sortedSeriesGroups(games).filter(x=>x.name!=='Tek Oyunlar').length, totalVideos, watchedVideos, completed, missing };
}
