/* FIX63B - Arama odağı, kaldığımız bölüm butonu ve form senkronizasyon rötuşları */
try{
  window.__HO240F63_SEARCH_TIMER__ = window.__HO240F63_SEARCH_TIMER__ || null;
  document.addEventListener('input', function(event){
    const target = event.target;
    if(!target || target.id !== 'searchInput') return;
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    const value = target.value || '';
    const cursor = target.selectionStart ?? value.length;
    state.query = value;
    window.clearTimeout(window.__HO240F63_SEARCH_TIMER__);
    window.__HO240F63_SEARCH_TIMER__ = window.setTimeout(()=>{
      render?.();
      requestAnimationFrame(()=>{
        const next = document.getElementById('searchInput');
        if(next){
          next.focus({ preventScroll:true });
          try{ next.setSelectionRange(cursor, cursor); }catch{}
        }
      });
    }, 120);
  }, true);
  document.addEventListener('click', function(event){
    const watch = event.target?.closest?.('[data-watch-series]');
    if(!watch) return;
    if(watch.dataset.watchSeriesEpisode === undefined) return;
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    const gameId = watch.dataset.watchSeries;
    const explicitIndex = Number(watch.dataset.watchSeriesEpisode || 0);
    const game = (state.games || []).find(g=>String(g.id) === String(gameId));
    if(game){
      const info = ho240f63ContinueInfo(game);
      const max = Math.max((info.episodes?.length || 1) - 1, 0);
      state.watchingGameId = game.id;
      state.selectedEpisodeId = null;
      state.selectedEpisodeIndex = Math.max(0, Math.min(Number.isFinite(explicitIndex) ? explicitIndex : 0, max));
      render?.();
    }
  }, true);
}catch(error){ console.warn('FIX63B arama/kaldığımız bölüm guard atlandı:', error); }
try{
  const ho240f63bPrevFields = typeof gameFormFields === 'function' ? gameFormFields : null;
  gameFormFields = function(d={}, mode='add'){
    let html = ho240f63bPrevFields ? ho240f63bPrevFields(d, mode) : '';
    const names = [...new Set((state.games || []).map(g=>String(g.seriesName || g.title || '').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr'));
    const datalist = `<datalist id="ho240f63SeriesSuggestions">${names.slice(0,120).map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist>`;
    html = html.replace(/(<input[^>]+name="seriesName"[^>]*)(>)/i, '$1 list="ho240f63SeriesSuggestions"$2');
    if(!html.includes('ho240f63SeriesSuggestions')) html += datalist;
    const syncButtons = `<button class="miniBtn primary" type="button" data-action="estimate-playlist-episodes">YouTube Senkronize Et</button><button class="miniBtn" type="button" data-action="ho240f63-sort-episodes">Bölümleri Sırala</button><button class="miniBtn danger" type="button" data-action="ho240f63-clear-episodes">Bölüm Listesini Temizle</button>`;
    if(!html.includes('YouTube Senkronize Et')) html = html.replace('</div></div>', `${syncButtons}</div></div>`);
    return html;
  };
  document.addEventListener('click', function(event){
    const actionEl = event.target?.closest?.('[data-action]');
    if(!actionEl) return;
    const action = actionEl.dataset.action || '';
    if(!['ho240f63-clear-episodes','ho240f63-sort-episodes'].includes(action)) return;
    event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation?.();
    const form = actionEl.closest?.('#gameAddForm,#gameEditForm,.gameForm') || document.querySelector('#gameEditForm,#gameAddForm,.gameForm');
    if(!form) return setToast?.('Oyun formu açık değil.');
    const textarea = form.elements?.episodesText || form.querySelector('[name="episodesText"]');
    if(action === 'ho240f63-clear-episodes'){
      if(textarea) textarea.value = '';
      if(form.elements?.eps) form.elements.eps.value = '0';
      if(form.elements?.watchedEps) form.elements.watchedEps.value = '0';
      textarea?.dispatchEvent(new Event('input', { bubbles:true }));
      return setToast?.('Bölüm listesi temizlendi. Kaydetmeden kalıcı olmaz.');
    }
    if(action === 'ho240f63-sort-episodes'){
      if(!textarea) return setToast?.('Bölüm listesi alanı bulunamadı.');
      const lines = String(textarea.value || '').split(/\n+/).map(x=>x.trim()).filter(Boolean);
      const sorted = lines.sort((a,b)=>{
        const na = Number((a.match(/(^|\D)(\d{1,4})(\D|$)/)||[])[2] || 9999);
        const nb = Number((b.match(/(^|\D)(\d{1,4})(\D|$)/)||[])[2] || 9999);
        return na - nb || a.localeCompare(b,'tr');
      });
      textarea.value = sorted.join('\n');
      textarea.dispatchEvent(new Event('input', { bubbles:true }));
      return setToast?.('Bölüm listesi sıraya alındı. Kaydetmeden kalıcı olmaz.');
    }
  }, true);
}catch(error){ console.warn('FIX63B form senkronizasyon rötuşları atlandı:', error); }
