/* v2.4.1 FIX64 - Seri kartları, menü taşması, bakım notları ve paket temizliği */
const HO240F64_INTERNAL_VERSION = 'v2.4.1 FIX 64';
const HO240F64_PUBLIC_VERSION = 'v2.4.1';
function ho240f64SafeText(value){ return String(value || '').toLocaleLowerCase('tr-TR'); }
function ho240f64StatusKey(game){
  const s = ho240f64SafeText(game?.status);
  if(s.includes('yak') || s.includes('plan') || s.includes('başlanmadı') || s.includes('baslanmadi')) return 'upcoming';
  if(s.includes('tamam') || s.includes('bitti') || s.includes('final')) return 'completed';
  const total = Number(game?.eps || (typeof seriesEpisodes === 'function' ? seriesEpisodes(game).length : 0) || 0);
  const watched = Number(game?.watchedEps || 0);
  const pct = typeof progressPercent === 'function' ? Number(progressPercent(game) || 0) : (total ? Math.round(watched / Math.max(total,1) * 100) : 0);
  if(total > 0 && watched >= total) return 'completed';
  if(s.includes('devam') || s.includes('aktif') || (total > 0 && watched > 0 && watched < total)) return 'ongoing';
  return 'archive';
}
function ho240f64IsResumeGame(game){
  if(!game) return false;
  if(ho240f64StatusKey(game) !== 'ongoing') return false;
  const total = Number(game.eps || (typeof seriesEpisodes === 'function' ? seriesEpisodes(game).length : 0) || 0);
  if(total <= 0) return false;
  return true;
}
function ho240f64GroupStats(group){
  const items = Array.isArray(group?.items) ? group.items : [];
  const totalEps = items.reduce((s,g)=>s+Number(g.eps || (typeof seriesEpisodes === 'function' ? seriesEpisodes(g).length : 0) || 0),0);
  const watched = items.reduce((s,g)=>s+Number(g.watchedEps || 0),0);
  const completed = items.filter(g=>ho240f64StatusKey(g)==='completed').length;
  const upcoming = items.filter(g=>ho240f64StatusKey(g)==='upcoming').length;
  const ongoing = items.filter(ho240f64IsResumeGame).length;
  let percent = totalEps ? Math.round(Math.max(0, watched) / Math.max(totalEps,1) * 100) : 0;
  if(items.length && completed === items.length) percent = 100;
  percent = Math.max(0, Math.min(100, percent));
  let key='archive', label='Arşiv', tone='neutral';
  if(items.length && upcoming === items.length){ key='upcoming'; label='Yakında'; tone='blue'; }
  else if(items.length && (completed === items.length || percent >= 100)){ key='completed'; label='Tamamlandı'; tone='green'; }
  else if(ongoing > 0){ key='ongoing'; label='Devam Ediyor'; tone='pink'; }
  return { games:items.length,totalEps,watched,completed,upcoming,ongoing,percent,key,label,tone };
}
function ho240f64NextItem(group){
  const items = Array.isArray(group?.items) ? group.items : [];
  return items.find(ho240f64IsResumeGame) || items.find(g=>ho240f64StatusKey(g)==='archive') || items[0] || {};
}
function ho240f64StatusBadge(stats){ return `<span class="ho240f40StatusBadge ${esc(stats.tone)}">${esc(stats.label)}</span>`; }
function ho240f64MiniList(items=[]){
  const arr = Array.isArray(items) ? items : [];
  return `<div class="ho240f40SeriesMiniList ho240f64AllMiniList">${arr.map((g,i)=>`<button type="button" data-watch-series="${esc(g.id)}"><img src="${esc(typeof fix10Cover==='function'?fix10Cover(g):coverFor(g))}" alt=""><b>${i+1}. ${esc(g.title)}</b><small>${esc(g.status || '')}</small></button>`).join('') || '<em>Alt oyun yok</em>'}</div>`;
}
function ho240f64ResumeLine(game){
  if(!ho240f64IsResumeGame(game)) return '';
  const info = typeof ho240f63ContinueInfo === 'function' ? ho240f63ContinueInfo(game) : (typeof ho240f59ContinueInfo === 'function' ? ho240f59ContinueInfo(game) : null);
  const ep = info?.current || info?.next;
  if(!ep) return '';
  const no = Number(ep.number || (info.currentIndex || 0) + 1 || 1);
  const name = typeof cleanEpisodeTitle === 'function' ? cleanEpisodeTitle(ep.title || `${no}. Bölüm`, no) : (ep.title || `${no}. Bölüm`);
  return `<div class="ho240f59MiniLine ho240f64ResumeOnly"><b>📍 Kaldığımız:</b> <span>${esc(no)}. Bölüm</span><small>${esc(String(name || '').slice(0,92))}</small></div>`;
}
