/* v2.4.1 FIX66 - Profesyonel kartlı oyun formu, ayrı otomasyon blokları, canlı önizleme ve kapak seçici */
const HO240F66_INTERNAL_VERSION = 'v2.4.1 FIX 66';
const HO240F66_PUBLIC_VERSION = 'v2.4.1';
function ho240f66SeriesNames(){
  try{
    const list = [...new Set((state.games || []).map(g=>String(g.seriesName || '').trim()).filter(Boolean))];
    return list.sort((a,b)=>a.localeCompare(b,'tr'));
  }catch{ return []; }
}
function ho240f66SeriesSuggestions(title=''){
  const names = ho240f66SeriesNames();
  const typed = String(title || '').trim().toLocaleLowerCase('tr-TR');
  const direct = names.filter(name=>typed && typed.includes(String(name).toLocaleLowerCase('tr-TR')));
  const starts = names.filter(name=>typed && String(name).toLocaleLowerCase('tr-TR').startsWith(typed.split(/[\-:|]/)[0]?.trim() || ''));
  const merged = [...new Set([...direct, ...starts, ...names])];
  return merged.slice(0,8);
}
function ho240f66GuessSeriesName(title=''){
  const typed = String(title || '').trim();
  if(!typed) return '';
  const names = ho240f66SeriesNames();
  const lower = typed.toLocaleLowerCase('tr-TR');
  const exact = names.find(name=>lower.includes(String(name).toLocaleLowerCase('tr-TR')));
  if(exact) return exact;
  const cut = typed.split(/\s*[:-]\s*/)[0]?.trim();
  if(cut && cut.length >= 3) return cut;
  const words = typed.split(/\s+/).slice(0,2).join(' ').trim();
  return words || typed;
}
function ho240f66PreviewCover(data){
  return esc(data.cover || '/assets/hayatimiz-kapak.png');
}
