try{
  document.addEventListener('click', function(event){
    const actionEl = event.target?.closest?.('[data-action]');
    if(actionEl){
      const action = actionEl.dataset.action || '';
      if(action === 'ho240f66-detect-series'){
        event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation?.();
        const form = actionEl.closest?.('#gameAddForm,#gameEditForm,.gameForm') || document.querySelector('#gameEditForm,#gameAddForm,.gameForm');
        if(!form) return setToast?.('Oyun formu açık değil.');
        const title = form.elements?.title?.value || '';
        const guessed = ho240f66GuessSeriesName(title);
        const input = form.elements?.seriesName || form.querySelector('[name="seriesName"]');
        if(input){ input.value = guessed; input.dispatchEvent(new Event('input', { bubbles:true })); }
        try{ if(typeof saveGameDraftFromForm === 'function') saveGameDraftFromForm(form); }catch{}
        try{ if(typeof updateOpenGameFormSnapshot === 'function') updateOpenGameFormSnapshot(form); }catch{}
        render?.();
        return setToast?.(guessed ? `Seri otomatik bulundu: ${guessed}` : 'Seri adı tahmin edilemedi.');
      }
      if(action === 'ho240f66-refresh-preview'){
        event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation?.();
        const form = actionEl.closest?.('#gameAddForm,#gameEditForm,.gameForm') || document.querySelector('#gameEditForm,#gameAddForm,.gameForm');
        if(form){
          try{ if(typeof saveGameDraftFromForm === 'function') saveGameDraftFromForm(form); }catch{}
          try{ if(typeof updateOpenGameFormSnapshot === 'function') updateOpenGameFormSnapshot(form); }catch{}
          render?.();
        }
        return setToast?.('Canlı önizleme yenilendi.');
      }
    }
    const pick = event.target?.closest?.('[data-ho240f66-series-pick]');
    if(pick){
      event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation?.();
      const form = pick.closest?.('#gameAddForm,#gameEditForm,.gameForm') || document.querySelector('#gameEditForm,#gameAddForm,.gameForm');
      const input = form?.elements?.seriesName || form?.querySelector?.('[name="seriesName"]');
      if(input){
        input.value = pick.dataset.ho240f66SeriesPick || '';
        input.dispatchEvent(new Event('input', { bubbles:true }));
        try{ if(typeof saveGameDraftFromForm === 'function') saveGameDraftFromForm(form); }catch{}
        try{ if(typeof updateOpenGameFormSnapshot === 'function') updateOpenGameFormSnapshot(form); }catch{}
        render?.();
        setToast?.(`Seri seçildi: ${input.value}`);
      }
    }
  }, true);
}catch(error){ console.warn('FIX66 click handlers atlandı:', error); }
