/* v2.4.1 FIX67 - Dosyadan kapak yükleme, büyük kapak galerisi ve YouTube senkron tablo sonucu */
const HO240F67_INTERNAL_VERSION = 'v2.4.1 FIX 67';
const HO240F67_PUBLIC_VERSION = 'v2.4.1';
function ho240f67EpisodeRowsFromText(text='', episodes=[]){
  const rows = [];
  if(Array.isArray(episodes) && episodes.length){
    episodes.forEach((ep, index)=>{
      rows.push({
        no: ep.number || ep.episode || index + 1,
        title: ep.title || ep.name || `${index + 1}. Bölüm`,
        duration: ep.duration || ep.length || '',
        url: ep.url || ep.videoUrl || ep.link || ''
      });
    });
  }
  if(!rows.length){
    String(text || '').split(/\n+/).map(x=>x.trim()).filter(Boolean).forEach((line,index)=>{
      const parts = line.split('|').map(x=>x.trim()).filter(Boolean);
      const numberMatch = line.match(/(?:^|\D)(\d{1,4})(?:\D|$)/);
      rows.push({
        no: numberMatch ? numberMatch[1] : index + 1,
        title: parts[0] || line.replace(/^[-*\d.\s]+/,'').slice(0,120) || `${index + 1}. Bölüm`,
        duration: (line.match(/(\d{1,2}:\d{2}(?::\d{2})?)/)||[])[1] || '',
        url: parts.find(p=>/^https?:\/\//i.test(p)) || ''
      });
    });
  }
  return rows.slice(0,160);
}
function ho240f67YoutubeTable(data={}){
  const rows = ho240f67EpisodeRowsFromText(data.episodesText || '', data.episodes || []);
  return `<section class="ho240f67YoutubeResult">
    <div class="ho240f67PanelHead"><div><span class="eyebrow">YouTube Sonuç Tablosu</span><h3>Senkronize edilen bölümler</h3><p class="muted">Playlist çekildikten sonra tüm videolar sırayla burada kontrol edilir. Silme yok; sadece formdaki bölüm listesi düzenlenir.</p></div><span class="pill green">${rows.length} video</span></div>
    ${rows.length ? `<div class="ho240f67TableWrap"><table class="ho240f67EpisodeTable"><thead><tr><th>#</th><th>Bölüm / Video Başlığı</th><th>Süre</th><th>Bağlantı</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(String(row.no))}</td><td><b>${esc(String(row.title).slice(0,140))}</b></td><td>${esc(row.duration || '-')}</td><td>${row.url?`<span class="pill">URL var</span>`:'<span class="muted">Yok</span>'}</td></tr>`).join('')}</tbody></table></div>` : `<div class="ho240f67EmptyResult"><b>Henüz video çekilmedi.</b><span>YouTube Senkronize Et butonuna basınca sonuçlar burada tablo olarak görünür.</span></div>`}
  </section>`;
}
