function ho240f67BuildTableHtmlFromForm(form){
  const text = form?.elements?.episodesText?.value || form?.querySelector?.('[name="episodesText"]')?.value || '';
  const rows = ho240f67EpisodeRowsFromText(text, []);
  return rows.length ? `<div class="ho240f67TableWrap"><table class="ho240f67EpisodeTable"><thead><tr><th>#</th><th>Bölüm / Video Başlığı</th><th>Süre</th><th>Bağlantı</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(String(row.no))}</td><td><b>${esc(String(row.title).slice(0,140))}</b></td><td>${esc(row.duration || '-')}</td><td>${row.url?`<span class="pill">URL var</span>`:'<span class="muted">Yok</span>'}</td></tr>`).join('')}</tbody></table></div>` : `<div class="ho240f67EmptyResult"><b>Henüz video çekilmedi.</b><span>YouTube Senkronize Et butonuna basınca sonuçlar burada tablo olarak görünür.</span></div>`;
}
function ho240f67RefreshYoutubePreview(form){
  const panel = form?.querySelector?.('.ho240f67YoutubeResult');
  if(!panel) return;
  const rows = ho240f67EpisodeRowsFromText(form.elements?.episodesText?.value || '', []);
  const badge = panel.querySelector('.pill.green');
  if(badge) badge.textContent = `${rows.length} video`;
  const old = panel.querySelector('.ho240f67TableWrap,.ho240f67EmptyResult');
  if(old) old.outerHTML = ho240f67BuildTableHtmlFromForm(form);
}
try{
  document.addEventListener('change', function(event){
    const input = event.target;
    if(!input || input.name !== 'coverFile' || !input.files || !input.files[0]) return;
    const form = input.closest?.('#gameAddForm,#gameEditForm,.gameForm');
    const file = input.files[0];
    if(!file.type || !file.type.startsWith('image/')) return setToast?.('Lütfen görsel dosyası seç.');
    if(file.size > 3 * 1024 * 1024) setToast?.('Kapak dosyası büyük. Yine de önizleme yapılacak; mümkünse 3 MB altı kullan.');
    const reader = new FileReader();
    reader.onload = function(){
      const dataUrl = String(reader.result || '');
      const coverInput = form?.elements?.cover || form?.querySelector?.('[name="cover"]');
      if(coverInput){
        coverInput.value = dataUrl;
        coverInput.dispatchEvent(new Event('input', { bubbles:true }));
      }
      form?.querySelectorAll?.('.coverPreview,.ho240f66CoverPreview,.fix6PreviewCover').forEach(box=>{
        const img = box.querySelector('img');
        if(img) img.src = dataUrl;
        else box.innerHTML = `<img src="${dataUrl}" alt="Kapak önizleme">`;
        box.classList.remove('isEmpty');
      });
      try{ if(typeof saveGameDraftFromForm === 'function') saveGameDraftFromForm(form); }catch{}
      try{ if(typeof updateOpenGameFormSnapshot === 'function') updateOpenGameFormSnapshot(form); }catch{}
      setToast?.('Kapak dosyası forma aktarıldı. Kaydetmeden kalıcı olmaz.');
    };
    reader.readAsDataURL(file);
  }, true);

  document.addEventListener('input', function(event){
    const filter = event.target?.closest?.('[data-ho240f67-cover-filter]');
    if(filter){
      const q = String(filter.value || '').toLocaleLowerCase('tr-TR').trim();
      const panel = filter.closest('.ho240f67CoverGallery');
      panel?.querySelectorAll?.('[data-ho240f67-cover-item]').forEach(item=>{
        item.style.display = !q || String(item.dataset.ho240f67CoverItem || '').includes(q) ? '' : 'none';
      });
      return;
    }
    if(event.target?.matches?.('#gameAddForm [name="episodesText"],#gameEditForm [name="episodesText"],.gameForm [name="episodesText"]')){
      const form = event.target.closest('#gameAddForm,#gameEditForm,.gameForm');
      window.clearTimeout(window.__HO240F67_YT_TIMER__);
      window.__HO240F67_YT_TIMER__ = window.setTimeout(()=>ho240f67RefreshYoutubePreview(form), 120);
    }
  }, true);

  document.addEventListener('click', function(event){
    const action = event.target?.closest?.('[data-action]')?.dataset?.action || '';
    if(action === 'estimate-playlist-episodes' || action === 'estimate-playlist-episodes-edit'){
      const form = event.target.closest?.('#gameAddForm,#gameEditForm,.gameForm') || document.querySelector('#gameEditForm,#gameAddForm,.gameForm');
      window.setTimeout(()=>ho240f67RefreshYoutubePreview(form), 900);
      window.setTimeout(()=>ho240f67RefreshYoutubePreview(form), 1800);
    }
  }, true);
}catch(error){ console.warn('FIX67 eventleri atlandı:', error); }

