function ho243ParseSteps(raw){
  return String(raw || '').split(/\n+/).map(line=>line.trim()).filter(Boolean).map((line,i)=>{
    const parts = line.split('|').map(x=>x.trim());
    if(parts.length >= 3) return { icon:parts[0] || '•', title:parts[1] || `Adım ${i+1}`, text:parts.slice(2).join(' | ') };
    if(parts.length === 2) return { icon:'•', title:parts[0], text:parts[1] };
    return { icon:'•', title:`Adım ${i+1}`, text:line };
  }).slice(0,12);
}
