const HO244_SOCIAL_KEY = 'hayatimiz_social_links_v244';
function ho244StoreNorm(value){
  return String(value || '').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9ığüşöçİĞÜŞÖÇ]+/gi,' ').replace(/\s+/g,' ').trim();
}
function ho244TitleScore(query='', candidate=''){
  const q = ho244StoreNorm(query); const c = ho244StoreNorm(candidate);
  if(!q || !c) return 0;
  if(q === c) return 100;
  if(c.includes(q) || q.includes(c)) return 88;
  const qs = new Set(q.split(' ').filter(Boolean));
  const cs = new Set(c.split(' ').filter(Boolean));
  let hit = 0; qs.forEach(w=>{ if(cs.has(w)) hit++; });
  return Math.round((hit / Math.max(qs.size,1)) * 74);
}
function ho244SafeDomain(url=''){
  try{ return new URL(String(url).startsWith('http') ? String(url) : `https://${url}`).hostname.replace(/^www\./,''); }catch{return '';}
}
function ho244Favicon(url=''){
  const domain = ho244SafeDomain(url) || String(url || '').replace(/^@/,'');
  return `https://www.google.com/s2/favicons?sz=64&domain_url=${encodeURIComponent(domain || 'youtube.com')}`;
}
function ho244ReadSocials(){
  try{ const rows = JSON.parse(localStorage.getItem(HO244_SOCIAL_KEY) || '[]'); if(Array.isArray(rows)) return rows; }catch{}
  return [];
}
function ho244SaveSocials(rows){
  localStorage.setItem(HO244_SOCIAL_KEY, JSON.stringify((rows || []).filter(x=>x && x.url)));
}
function ho244SocialLabel(url=''){
  const d = ho244SafeDomain(url);
  if(d.includes('youtube')) return 'YouTube';
  if(d.includes('instagram')) return 'Instagram';
  if(d.includes('discord')) return 'Discord';
  if(d.includes('x.com') || d.includes('twitter')) return 'X';
  if(d.includes('tiktok')) return 'TikTok';
  if(d.includes('facebook')) return 'Facebook';
  if(d.includes('twitch')) return 'Twitch';
  return d || 'Sosyal Medya';
}
function ho244SocialIcons(){
  const rows = ho244ReadSocials().slice(0,8);
  if(!rows.length) return '';
  return `<div class="ho244SocialIcons">${rows.map((item,i)=>`<a href="${esc(item.url)}" target="_blank" rel="noopener" title="${esc(item.title || ho244SocialLabel(item.url))}"><img src="${esc(item.icon || ho244Favicon(item.url))}" alt="${esc(item.title || ho244SocialLabel(item.url))}" onerror="this.style.display='none'"></a>`).join('')}</div>`;
}
function ho244StoreLinks(title=''){
  const q = encodeURIComponent(String(title || '').trim());
  return [
    { source:'Steam', domain:'store.steampowered.com', icon:ho244Favicon('store.steampowered.com'), url:`https://store.steampowered.com/search/?term=${q}`, action:'ho240f58-steam-check' },
    { source:'Epic Games', domain:'store.epicgames.com', icon:ho244Favicon('store.epicgames.com'), url:`https://store.epicgames.com/tr/browse?q=${q}&sortBy=relevancy&sortDir=DESC&count=40`, action:'ho244-store-check', store:'epic' },
    { source:'Ubisoft', domain:'ubisoft.com', icon:ho244Favicon('ubisoft.com'), url:`https://www.ubisoft.com/tr-tr/search?search=${q}`, action:'ho244-store-check', store:'ubisoft' }
  ];
}
