  if(!rows.length) return `<section class="ho244YoutubeTable empty"><div><b>YouTube Senkronizasyon Tablosu</b><span>Playlist senkronize edilince videolar otomatik bölüm tablosuna işlenecek.</span></div></section>`;
  return `<section class="ho244YoutubeTable"><div class="ho244TableHead"><div><b>YouTube Senkronizasyon Tablosu</b><span>${rows.length} video / bölüm otomatik işlendi</span></div><span class="pill green">Profesyonel Liste</span></div><div class="tableWrap"><table><thead><tr><th>#</th><th>Kapak</th><th>Başlık</th><th>Yayın</th><th>Video</th></tr></thead><tbody>${rows.map(ep=>`<tr><td>${esc(String(ep.number || ''))}</td><td>${ep.thumbnail?`<img src="${esc(ep.thumbnail)}" onerror="this.style.display='none'">`:'-'}</td><td><b>${esc(ep.title || '')}</b></td><td>${esc(ep.publishAt || '-')}</td><td>${ep.videoUrl?`<a target="_blank" rel="noopener" href="${esc(ep.videoUrl)}">Aç</a>`:'Link yok'}</td></tr>`).join('')}</tbody></table></div></section>`;
