function ho244CandidateScore(c, typed){
  const titleScore = ho244TitleScore(typed, c?.title || c?.name || '');
  const source = String(c?.source || '').toLocaleLowerCase('tr-TR');
  const bonus = source.includes('steam') ? 8 : source.includes('yerel') || source.includes('local') ? 6 : 0;
  return Math.max(Number(c?.matchScore || 0), titleScore) + bonus;
}
