    html = html.replace(/(<div class="[^"]*(?:Cover|coverWrap|GameCover|v221GameCover|fix12GameCover)[^"]*"[^>]*>\s*<img[^>]*>)/, `$1${badges}`);
    html = html.replace(/(class="[^"]*(?:game|GameCard|v221GameCard|fix12GameCard)[^"]*)"/, '$1 ho245StableCard"');
