/* v2.4.6 - Seri İzleme Ekranı, Profesyonel Bakım Merkezi ve Supabase Sürüm Güncellemesi */
const HO246_INTERNAL_VERSION = 'v2.4.6';
const HO246_PUBLIC_VERSION = 'v2.4.6';
function ho246Num(v){ const n=Number(v); return Number.isFinite(n) ? n : null; }
function ho246Score(g={}){
  const keys = ['gameplayScore','gameplay_score','storyScore','story_score','visualScore','visual_score','audioScore','audio_score','atmosphereScore','atmosphere_score','score'];
  const vals = keys.map(k=>ho246Num(g[k])).filter(v=>v!==null && v>0 && v<=10);
  if(!vals.length) return '-';
  const avg = vals.reduce((a,b)=>a+b,0)/vals.length;
  return avg.toFixed(1).replace('.0','');
}
function ho246VersionNotes(){
  const fallback = [
    {version:'v2.4.6', title:'Seri İzleme Ekranı Geliştirme', summary:'Seriler daha okunaklı, bakım modu daha profesyonel ve güncelleme notları otomatik gösterilir.'},
    {version:'v2.4.5', title:'Profesyonel Oyun Formu ve Bakım Merkezi', summary:'Oyun formu, YouTube tablosu, toplu silme ve form sıfırlama eklendi.'},
    {version:'v2.4.4', title:'Mağaza, Sosyal Medya ve YouTube Doğrulama', summary:'Steam, Epic Games, Ubisoft kontrolü ve sosyal medya yönetimi eklendi.'},
    {version:'v2.4.3', title:'İlk Kullanım Rehberi', summary:'Site tanıtım rehberi ve hikâye açıklaması iyileştirildi.'},
    {version:'v2.4.2', title:'Yayın Öncesi Test Merkezi', summary:'Açılışa hazır/hazır değil kontrol merkezi eklendi.'}
  ];
  try{
    const rows = Array.isArray(VERSION_NOTES_ARCHIVE) ? VERSION_NOTES_ARCHIVE : [];
    const out = [];
    [...rows, ...fallback].forEach(n=>{
      if(!n || !n.version || out.some(x=>String(x.version)===String(n.version))) return;
      out.push({version:n.version, title:n.title || 'Güncelleme', summary:n.summary || n.written || n.note || ''});
    });
    return out.slice(0,5);
  }catch{ return fallback.slice(0,5); }
}
function ho246MaintNotesFromVersions(){
  return ho246VersionNotes().map(n=>`${n.version} - ${n.title}: ${String(n.summary || '').slice(0,140)}`);
}
function ho246MaintNotes(){
  const m = state.maintenance || {};
  const raw = String(m.notesText || m.publicNotes || m.notes || m.updates || '').trim();
  if(raw) return raw.split(/\n+/).map(x=>x.trim()).filter(Boolean).slice(0,5);
  return ho246MaintNotesFromVersions().slice(0,5);
}
function ho246MaintData(){
  const m = state.maintenance || {};
  const p = Math.max(0, Math.min(100, Number(m.progress ?? m.percent ?? 0)));
  return {m,p,notes:ho246MaintNotes(), versions:ho246VersionNotes()};
}
function ho246CollectMaintenance(openState){
  const current = state.maintenance || {};
  const message = document.getElementById('maintenanceMessage')?.value || current.message || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.';
  const eta = document.getElementById('maintenanceEta')?.value || current.eta || '';
  const progress = Math.max(0, Math.min(100, Number(document.getElementById('maintenanceProgress')?.value || current.progress || current.percent || 0)));
  const notesText = document.getElementById('maintenanceNotesText')?.value || ho246MaintNotesFromVersions().join('\n');
  const enabled = typeof openState === 'boolean' ? openState : Boolean(current.enabled);
  const maintenance = { ...current, enabled, message, eta, progress, percent:progress, notesText, publicNotes:notesText, version:HO246_PUBLIC_VERSION, updatedAt:new Date().toISOString() };
  state.maintenance = maintenance;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(maintenance)); }catch{}
  return maintenance;
}
async function ho246SaveMaintenance(openState){
  const maintenance = ho246CollectMaintenance(openState);
  try{ await api('settings-set', { adminToken:state.session?.adminToken, maintenance }); }catch(err){ console.warn('v2.4.6 bakım Supabase kaydı atlandı:', err); }
  return maintenance;
}
