    const avg = ho246Score(g);
    html = html.replace(/<span class="scoreBadge([^">]*)">[\s\S]*?<\/span>/, `<span class="scoreBadge$1 ho246ScoreBadge"><small>Ort.</small>${esc(String(avg))}</span>`);
