function ho246f1VersionNotes(){
  const fallback = [
    {version:'v2.4.6 FIX1', title:'Seri ve Bakım Modu Görsel Düzeltmeleri', summary:'Seriler kompakt/alphabetik oldu, bakım modu profesyonel kaydet/aç/kapat ekranına döndü.'},
    {version:'v2.4.6', title:'Seri İzleme Ekranı Geliştirme', summary:'Seri izleme ekranı ve bakım notları güçlendirildi.'},
    {version:'v2.4.5', title:'Profesyonel Oyun Formu', summary:'Oyun formu, bakım merkezi ve toplu silme eklendi.'},
    {version:'v2.4.4', title:'Mağaza, Sosyal ve YouTube', summary:'Steam/Epic/Ubisoft kontrolü ve sosyal medya yönetimi eklendi.'},
    {version:'v2.4.3', title:'İlk Kullanım Rehberi', summary:'Site rehberi ve hikaye açıklamaları iyileştirildi.'}
  ];
  try{
    const rows = Array.isArray(VERSION_NOTES_ARCHIVE) ? VERSION_NOTES_ARCHIVE : [];
    const out = [];
    [...fallback, ...rows].forEach(n=>{ if(n?.version && !out.some(x=>String(x.version)===String(n.version))) out.push({version:n.version,title:n.title||'Güncelleme',summary:n.summary||n.written||''}); });
    return out.slice(0,5);
  }catch{ return fallback; }
}
function ho246f1MaintenanceData(){
  const m = state.maintenance || {};
  const p = Math.max(0, Math.min(100, Number(m.progress ?? m.percent ?? 0)));
  const raw = String(m.notesText || m.publicNotes || '').trim();
  const notes = raw ? raw.split(/\n+/).map(x=>x.trim()).filter(Boolean).slice(0,5) : ho246f1VersionNotes().map(n=>`${n.version} - ${n.title}: ${String(n.summary||'').slice(0,120)}`).slice(0,5);
  return {m,p,notes,versions:ho246f1VersionNotes()};
}
function ho246f1CollectMaintenance(openState){
  const current = state.maintenance || {};
  const message = document.getElementById('maintenanceMessage')?.value || current.message || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.';
  const eta = document.getElementById('maintenanceEta')?.value || current.eta || '';
  const progress = Math.max(0, Math.min(100, Number(document.getElementById('maintenanceProgress')?.value || current.progress || current.percent || 0)));
  const notesText = document.getElementById('maintenanceNotesText')?.value || ho246f1VersionNotes().map(n=>`${n.version} - ${n.title}: ${n.summary}`).join('\n');
  const enabled = typeof openState === 'boolean' ? openState : Boolean(current.enabled);
  const maintenance = { ...current, enabled, message, eta, progress, percent:progress, notesText, publicNotes:notesText, version:HO246F1_PUBLIC_VERSION, updatedAt:new Date().toISOString() };
  state.maintenance = maintenance;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(maintenance)); }catch{}
  return maintenance;
}
async function ho246f1SaveMaintenance(openState){
  const maintenance = ho246f1CollectMaintenance(openState);
  try{ await api('settings-set', { adminToken:state.session?.adminToken, maintenance }); }catch(err){ console.warn('FIX1 bakım Supabase kaydı atlandı:', err); }
  return maintenance;
}
