/* v2.4.6 FIX2 - Tür/Etiket ayrımı ve Steam puanı otomatik çekme */
const HO246F2_INTERNAL_VERSION = 'v2.4.6 FIX2';
const HO246F2_PUBLIC_VERSION = 'v2.4.6';
const HO246F2_ALLOWED_TAGS = ['Türkçe Altyazılı','Türkçe Dublajlı','DLC','Coop','%100','Tek Oyunculu','Çok Oyunculu','Online','Hikaye','Açık Dünya','Rehber','Final'];
const HO246F2_TAG_KEY = new Map(HO246F2_ALLOWED_TAGS.map(t=>[String(t).toLocaleLowerCase('tr-TR'), t]));
const HO246F2_GENRE_WORDS = new Set(['aksiyon','macera','rpg','fps','tps','gizlilik','korku','gerilim','simülasyon','simulasyon','spor','yarış','yaris','strateji','bulmaca','platform','arcade','western','fantastik','bilim kurgu','soulslike','metroidvania','hayatta kalma','survival horror','aksiyon macera','psikolojik korku','psikolojik gerilim','açık dünya','acik dunya']);
function ho246f2List(value=''){
  return String(value || '').split(/[;,|/]+/).map(x=>x.trim()).filter(Boolean);
}
function ho246f2CleanTagList(value=''){
  const out=[];
  const seen=new Set();
  for(const raw of ho246f2List(value)){
    const k=String(raw).toLocaleLowerCase('tr-TR');
    const official=HO246F2_TAG_KEY.get(k);
    if(!official) continue;
    const key=official.toLocaleLowerCase('tr-TR');
    if(seen.has(key)) continue;
    seen.add(key); out.push(official);
  }
  return out;
}
function ho246f2CleanTags(value=''){ return ho246f2CleanTagList(value).join(', '); }
function ho246f2CleanGenre(value=''){
  const out=[]; const seen=new Set();
  for(const raw of ho246f2List(value)){
    const k=String(raw).toLocaleLowerCase('tr-TR');
    if(HO246F2_TAG_KEY.has(k) && !HO246F2_GENRE_WORDS.has(k)) continue;
    if(seen.has(k)) continue;
    seen.add(k); out.push(raw);
  }
  return out.join(', ');
}
function ho246f2PatchClean(patch={}){
  const next={...(patch||{})};
  if('genre' in next) next.genre = ho246f2CleanGenre(next.genre);
  if('tags' in next){
    const clean = ho246f2CleanTags(next.tags);
    const genreClean = ho246f2CleanGenre(next.genre || '');
    next.tags = clean;
    if(!clean && genreClean && String(next.tags||'').toLocaleLowerCase('tr-TR') === genreClean.toLocaleLowerCase('tr-TR')) delete next.tags;
  }
  return next;
}
function ho246f2ToggleTag(value, tag){
  const list = ho246f2CleanTagList(value);
  const official = HO246F2_TAG_KEY.get(String(tag||'').toLocaleLowerCase('tr-TR')) || tag;
  const key = String(official || '').toLocaleLowerCase('tr-TR');
  const exists = list.some(x=>String(x).toLocaleLowerCase('tr-TR')===key);
  return exists ? list.filter(x=>String(x).toLocaleLowerCase('tr-TR')!==key).join(', ') : [...list, official].join(', ');
}
