/* v2.4.6 FIX5 - Bakım Modu Kaydet / Aç / Kapat butonları görünürlük düzeltmesi */
const HO246F5_INTERNAL_VERSION = 'v2.4.6 FIX5';
const HO246F5_PUBLIC_VERSION = 'v2.4.6';
function ho246f5VersionNotes(){
  const fallback = [
    {version:'v2.4.6 FIX5', title:'Bakım Modu Buton Düzeltmesi', summary:'Kaydet, Bakımı Aç, Bakımı Kapat ve Önizle butonları mobilde ve masaüstünde görünür hale getirildi.'},
    {version:'v2.4.6 FIX4', title:'Schema Güncelleme Notları Düzeltmesi', summary:'site_update_notes kolonları güvenli hale getirildi.'},
    {version:'v2.4.6 FIX3', title:'Steam Puanı Katı Kural', summary:'Steam puanı yoksa eski/mevcut puan kullanılmaz.'},
    {version:'v2.4.6 FIX2', title:'Tür/Etiket Ayrımı', summary:'Tür ve etiket seçimleri birbirinden ayrıldı.'},
    {version:'v2.4.6 FIX1', title:'Seri ve Bakım Modu Görsel Düzeltmeleri', summary:'Seriler kompakt, bakım modu profesyonel görünüme alındı.'}
  ];
  try{
    const rows = Array.isArray(VERSION_NOTES_ARCHIVE) ? VERSION_NOTES_ARCHIVE : [];
    const out = [];
    [...fallback, ...rows].forEach(n=>{
      if(n?.version && !out.some(x=>String(x.version)===String(n.version))){
        out.push({ version:n.version, title:n.title || 'Güncelleme', summary:n.summary || n.written || n.description || '' });
      }
    });
    return out.slice(0,5);
  }catch{ return fallback; }
}
function ho246f5SafePercent(v){ return Math.max(0, Math.min(100, Number(v || 0) || 0)); }
function ho246f5MaintState(){
  const m = state.maintenance || {};
  const progress = ho246f5SafePercent(m.progress ?? m.percent ?? 0);
  const raw = String(m.notesText || m.publicNotes || '').trim();
  const notes = raw ? raw.split(/\n+/).map(x=>x.trim()).filter(Boolean).slice(0,5) : ho246f5VersionNotes().map(n=>`${n.version} - ${n.title}: ${String(n.summary || '').slice(0,130)}`).slice(0,5);
  return { m, progress, notes, versions:ho246f5VersionNotes() };
}
function ho246f5ActionBar(m, placement='top'){
  const enabled = Boolean(m?.enabled);
  const status = enabled ? 'Bakım açık' : 'Bakım kapalı';
  const primaryAction = enabled ? 'ho246f5-maint-close' : 'ho246f5-maint-open';
  const primaryText = enabled ? 'Bakımı Kapat' : 'Bakımı Aç';
  return `<div class="ho246f5ActionBar ${placement}" style="display:flex!important;visibility:visible!important;opacity:1!important;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between;margin:14px 0;padding:14px;border:1px solid rgba(255,255,255,.14);border-radius:18px;background:linear-gradient(135deg,rgba(255,47,63,.14),rgba(255,255,255,.055));position:relative;z-index:20;">
    <span class="pill ${enabled?'banned':'green'}" style="display:inline-flex!important;visibility:visible!important;">${status}</span>
    <div class="rowActions ho246f5VisibleActions" style="display:flex!important;visibility:visible!important;opacity:1!important;gap:8px;flex-wrap:wrap;align-items:center;justify-content:flex-end;">
      <button type="button" class="btn primary" data-action="ho246f5-maint-save" style="display:inline-flex!important;visibility:visible!important;">Kaydet</button>
      <button type="button" class="btn" data-action="ho246f5-maint-preview" style="display:inline-flex!important;visibility:visible!important;">Önizle</button>
      <button type="button" class="btn ${enabled?'danger':'primary'}" data-action="${primaryAction}" style="display:inline-flex!important;visibility:visible!important;">${primaryText}</button>
    </div>
  </div>`;
}
function ho246f5CollectMaintenance(openState){
  const current = state.maintenance || {};
  const message = document.getElementById('maintenanceMessage')?.value || current.message || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.';
  const eta = document.getElementById('maintenanceEta')?.value || current.eta || '';
  const progress = ho246f5SafePercent(document.getElementById('maintenanceProgress')?.value ?? current.progress ?? current.percent ?? 0);
  let notesText = document.getElementById('maintenanceNotesText')?.value || '';
  if(!String(notesText).trim()) notesText = ho246f5VersionNotes().map(n=>`${n.version} - ${n.title}: ${n.summary}`).slice(0,5).join('\n');
  const enabled = typeof openState === 'boolean' ? openState : Boolean(current.enabled);
  const maintenance = { ...current, enabled, message, eta, progress, percent:progress, notesText, publicNotes:notesText, version:HO246F5_PUBLIC_VERSION, fixVersion:HO246F5_INTERNAL_VERSION, updatedAt:new Date().toISOString() };
  state.maintenance = maintenance;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(maintenance)); }catch{}
  return maintenance;
}
async function ho246f5SaveMaintenance(openState){
  const maintenance = ho246f5CollectMaintenance(openState);
  try{ await api('settings-set', { adminToken:state.session?.adminToken, maintenance }); }catch(err){ console.warn('FIX5 bakım ayarı Supabase kaydı atlandı:', err); }
  return maintenance;
}
