function ho247SeriesGroupStats(group){
  const items = group?.items || [];
  const eps = items.reduce((s,g)=>s+Number(g.eps||seriesEpisodes(g).length||0),0);
  const watched = items.reduce((s,g)=>s+Number(g.watchedEps||0),0);
  const scoreList = items.map(g=>Number(g.score||0)).filter(n=>Number.isFinite(n)&&n>0);
  const avg = scoreList.length ? (scoreList.reduce((a,b)=>a+b,0)/scoreList.length).toFixed(1).replace('.0','') : 'Puan yok';
  return {eps,watched,avg,percent:eps?Math.round(watched/eps*100):0};
}
