function ho247ParseScore(value){
  if(value === undefined || value === null || value === '') return null;
  const raw = String(value).replace(',', '.').match(/\d+(?:\.\d+)?/);
  if(!raw) return null;
  const n = Number(raw[0]);
  if(!Number.isFinite(n) || n <= 0) return null;
  return Math.max(0, Math.min(10, n > 10 ? n/10 : n));
}
async function ho247PullScore(form){
  if(!form) return setToast?.('Oyun formu açık değil.');
  const title = String(form.elements?.title?.value || '').trim();
  if(!title) return setToast?.('Önce oyun adını yaz.');
  const scoreEl = form.elements?.score || form.querySelector('[name="score"]');
  try{
    const data = await api('score-check', {adminToken:state.session?.adminToken, title});
    const score = ho247ParseScore(data?.score || data?.averageScore || data?.avg);
    if(score && scoreEl){
      scoreEl.value = score.toFixed(1).replace('.0','');
      scoreEl.dispatchEvent(new Event('input',{bubbles:true}));
      scoreEl.dispatchEvent(new Event('change',{bubbles:true}));
      try{ if(typeof saveGameDraftFromForm==='function') saveGameDraftFromForm(form); }catch{}
      try{ if(typeof updateOpenGameFormSnapshot==='function') updateOpenGameFormSnapshot(form); }catch{}
      setToast?.(`Puan çekildi: ${scoreEl.value}/10 (${data?.sources?.length || 1} kaynak ortalaması).`);
      return true;
    }
    if(scoreEl){ scoreEl.value=''; scoreEl.placeholder='Puan bulunamadı'; scoreEl.dispatchEvent(new Event('input',{bubbles:true})); }
    setToast?.('Steam/Google puanı bulunamadı. Varsayılan puan kullanılmadı.');
  }catch(error){
    if(scoreEl){ scoreEl.value=''; scoreEl.placeholder='Puan çekilemedi'; scoreEl.dispatchEvent(new Event('input',{bubbles:true})); }
    setToast?.('Puan çekilemedi. Varsayılan puan kullanılmadı.');
  }
  return false;
}
