/* v2.4.7 FIX2 - Bakım Modu Kaydet / Aç / Kapat butonları kesin görünürlük düzeltmesi */
const HO247F2_INTERNAL_VERSION = 'v2.4.7 FIX2';
function ho247f2ClampPercent(value){
  const n = Number(value || 0);
  if(!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(100, Math.round(n)));
}
function ho247f2Maintenance(){
  return { ...(state.maintenance || {}), enabled: !!(state.maintenance && state.maintenance.enabled) };
}
function ho247f2VersionNotes(){
  const archive = Array.isArray(typeof VERSION_NOTES_ARCHIVE !== 'undefined' ? VERSION_NOTES_ARCHIVE : null) ? VERSION_NOTES_ARCHIVE : [];
  const fallback = [
    {version:'v2.4.7 FIX2', title:'Bakım Modu Butonları', summary:'Kaydet, Önizle, Bakımı Aç ve Bakımı Kapat butonları sabit görünür hale getirildi.'},
    {version:'v2.4.7 FIX1', title:'Seriler Altında Oyunlar', summary:'Seri kartlarında bağlı oyunlar görünür hale getirildi.'},
    {version:'v2.4.7', title:'Profesyonel UI ve XP/Level', summary:'Seriler, videolar, rehber ve puan sistemi geliştirildi.'},
    {version:'v2.4.6 FIX9', title:'Steam Eksik Tamamlama', summary:'Steam kontrolü eksik alanları dolduracak şekilde güçlendirildi.'},
    {version:'v2.4.6', title:'Seri ve Bakım Merkezi', summary:'Seri izleme ve bakım yönetimi geliştirildi.'}
  ];
  const merged = [...archive, ...fallback];
  const seen = new Set();
  return merged.filter(n=>{
    const key = String(n.version || n.title || '').trim();
    if(!key || seen.has(key)) return false;
    seen.add(key); return true;
  }).slice(0,5);
}
function ho247f2NotesText(m){
  const raw = String(m.notesText || m.publicNotes || m.notes || '').trim();
  if(raw) return raw.split(/\n+/).map(x=>x.trim()).filter(Boolean).slice(0,8);
  return ho247f2VersionNotes().map(n=>`${n.version} • ${n.title}: ${n.summary || n.written || ''}`.trim()).slice(0,5);
}
function ho247f2CollectMaintenanceForm(){
  const current = ho247f2Maintenance();
  const get = (id, fallback='') => {
    const el = document.getElementById(id);
    return el ? String(el.value ?? '') : fallback;
  };
  const notes = get('maintenanceNotesText', current.notesText || current.publicNotes || ho247f2NotesText(current).join('\n'));
  const next = {
    ...current,
    message: get('maintenanceMessage', current.message || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.').trim() || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.',
    eta: get('maintenanceEta', current.eta || '').trim(),
    progress: ho247f2ClampPercent(get('maintenanceProgress', current.progress || current.percent || 0)),
    percent: ho247f2ClampPercent(get('maintenanceProgress', current.progress || current.percent || 0)),
    notesText: notes,
    publicNotes: notes,
    updatedAt: new Date().toISOString()
  };
  state.maintenance = next;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(next)); }catch{}
  try{ localStorage.setItem('hayatimiz_maintenance', JSON.stringify(next)); }catch{}
  return next;
}
async function ho247f2PersistMaintenance(enabled){
  const next = ho247f2CollectMaintenanceForm();
  if(typeof enabled === 'boolean') next.enabled = enabled;
  state.maintenance = next;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(next)); }catch{}
  try{ localStorage.setItem('hayatimiz_maintenance', JSON.stringify(next)); }catch{}
  const payloads = [
    ['settings-set', { adminToken: state.session?.adminToken, maintenance: next }],
    ['runtime-config-upsert', { adminToken: state.session?.adminToken, key:'maintenance', value: next }],
    ['site-runtime-config-upsert', { adminToken: state.session?.adminToken, key:'maintenance', value: next }],
    ['maintenance-save', { adminToken: state.session?.adminToken, maintenance: next }]
  ];
  for(const [name, payload] of payloads){ try{ await api(name, payload); break; }catch{} }
  try{ render?.(); }catch{}
  if(typeof enabled === 'boolean') setToast?.(enabled ? 'Bakım modu açıldı ve kaydedildi.' : 'Bakım modu kapatıldı ve kaydedildi.');
  else setToast?.('Bakım modu ayarları kaydedildi.');
  return next;
}
