function ho247f3Maint(){ return { ...(state.maintenance || {}), enabled: !!(state.maintenance && state.maintenance.enabled) }; }
function ho247f3LatestNotes(){
  const archive = Array.isArray(typeof VERSION_NOTES_ARCHIVE !== 'undefined' ? VERSION_NOTES_ARCHIVE : null) ? VERSION_NOTES_ARCHIVE : [];
  const fallback = [
    {version:'v2.4.7 FIX3', title:'Bakım Modu ve Puan Çekme Düzeltmesi', summary:'Bakım modu gerçek Kaydet/Aç/Kapat butonlarına kavuştu; puan çekme ayrı çalışır.'},
    {version:'v2.4.7 FIX2', title:'Bakım Modu Butonları', summary:'Buton görünürlüğü güçlendirildi.'},
    {version:'v2.4.7 FIX1', title:'Seriler Altında Oyunlar', summary:'Seri kartlarında bağlı oyunlar listelendi.'},
    {version:'v2.4.7', title:'Profesyonel UI', summary:'Puan, video, seri ve rehber alanları geliştirildi.'},
    {version:'v2.4.6 FIX9', title:'Steam Eksik Tamamlama', summary:'Steam kontrolü eksik alanları doldurur.'}
  ];
  const seen = new Set();
  return [...fallback, ...archive].filter(n=>{ const key=String(n.version||n.title||'').trim(); if(!key||seen.has(key)) return false; seen.add(key); return true; }).slice(0,5);
}
function ho247f3NotesArray(m){
  const raw = String(m.notesText || m.publicNotes || m.notes || '').trim();
  if(raw) return raw.split(/\n+/).map(x=>x.trim()).filter(Boolean).slice(0,8);
  return ho247f3LatestNotes().map(n=>`${n.version} • ${n.title}: ${n.summary || n.written || ''}`.trim()).slice(0,5);
}
function ho247f3CollectMaint(){
  const cur = ho247f3Maint();
  const val = (id, fb='') => { const el=document.getElementById(id); return el ? String(el.value ?? '') : fb; };
  const notes = val('maintenanceNotesText', cur.notesText || cur.publicNotes || ho247f3NotesArray(cur).join('\n'));
  const p = ho247f3ClampPercent(val('maintenanceProgress', cur.progress || cur.percent || 0));
  const next = {
    ...cur,
    message: val('maintenanceMessage', cur.message || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.').trim() || 'Hayatımız Oyun kısa süreli bakımda. Yeni güncelleme hazırlanıyor.',
    eta: val('maintenanceEta', cur.eta || '').trim(),
    progress:p,
    percent:p,
    notesText:notes,
    publicNotes:notes,
    updatedAt:new Date().toISOString()
  };
  state.maintenance = next;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(next)); }catch{}
  try{ localStorage.setItem('hayatimiz_maintenance', JSON.stringify(next)); }catch{}
  try{ localStorage.setItem('hayatimiz_site_maintenance', JSON.stringify(next)); }catch{}
  return next;
}
async function ho247f3SaveMaint(enabled){
  const next = ho247f3CollectMaint();
  if(typeof enabled === 'boolean') next.enabled = enabled;
  state.maintenance = next;
  try{ localStorage.setItem('hayatimiz_maintenance_config', JSON.stringify(next)); }catch{}
  try{ localStorage.setItem('hayatimiz_maintenance', JSON.stringify(next)); }catch{}
  try{ localStorage.setItem('hayatimiz_site_maintenance', JSON.stringify(next)); }catch{}
  const payloads = [
    ['settings-set',{adminToken:state.session?.adminToken, maintenance:next}],
    ['runtime-config-upsert',{adminToken:state.session?.adminToken,key:'maintenance',value:next}],
    ['site-runtime-config-upsert',{adminToken:state.session?.adminToken,key:'maintenance',value:next}],
    ['maintenance-save',{adminToken:state.session?.adminToken,maintenance:next}]
  ];
  let savedRemote = false;
  for(const [action,payload] of payloads){
    try{ const r = await api(action,payload); if(r && r.ok !== false){ savedRemote = true; break; } }catch{}
  }
  try{ render?.(); }catch{}
  if(typeof enabled === 'boolean') setToast?.(enabled ? 'Bakım modu açıldı ve kaydedildi.' : 'Bakım modu kapatıldı ve kaydedildi.');
  else setToast?.(savedRemote ? 'Bakım modu ayarları kaydedildi.' : 'Bakım modu ayarları local kaydedildi; Supabase bağlantısını kontrol et.');
  return next;
}
function ho247f3ButtonPanel(m, label='Ana İşlemler'){
  const enabled = !!m.enabled;
  return `<section class="ho247f3ActionPanel">
    <div class="ho247f3ActionHead"><b>${label}</b><span class="pill ${enabled?'banned':'green'}">${enabled?'Bakım açık':'Bakım kapalı'}</span></div>
    <div class="ho247f3ButtonGrid" style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;width:100%;">
      <button class="btn primary ho247f3Btn" type="button" data-action="ho247f3-save-maintenance">Kaydet</button>
      <button class="btn ho247f3Btn" type="button" data-action="ho247f3-preview-maintenance">Önizle</button>
      <button class="btn primary ho247f3Btn" type="button" data-action="ho247f3-open-maintenance">Bakımı Aç</button>
      <button class="btn danger ho247f3Btn" type="button" data-action="ho247f3-close-maintenance">Bakımı Kapat</button>
    </div>
  </section>`;
}
function ho247f3Progress(p){ return `<div class="ho247f3Progress"><i style="width:${p}%"></i><b>${p}%</b></div>`; }
