/* v2.4.7 FIX7 - Video kapak, seri oyun listesi, canlı puan/youtube ve kalıcı bakım kaydı */
const HO247F7_INTERNAL_VERSION = 'v2.4.7 FIX7';
const HO247F7_PUBLIC_VERSION = 'v2.4.7';
function ho247f7Csv(value){ return String(value || '').split(/[,;|]/).map(x=>x.trim()).filter(Boolean); }
function ho247f7Key(value){ return String(value || '').toLocaleLowerCase('tr-TR').replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ş/g,'s').replace(/ö/g,'o').replace(/ç/g,'c'); }
const HO247F7_TAGS = new Set(['turkce altyazili','turkce dublajli','dlc','coop','co-op','100','%100','tek oyunculu','cok oyunculu','online','hikaye','rehber','final']);
function ho247f7SplitGenreTags(game){
  const genreRaw = ho247f7Csv(game?.genre);
  const tagRaw = ho247f7Csv(game?.tags);
  const genres=[], tags=[];
  const pushUnique=(arr,v)=>{ if(v && !arr.some(x=>ho247f7Key(x)===ho247f7Key(v))) arr.push(v); };
  genreRaw.forEach(v=>{ const k=ho247f7Key(v); if(HO247F7_TAGS.has(k)) pushUnique(tags,v); else pushUnique(genres,v); });
  tagRaw.forEach(v=>{ const k=ho247f7Key(v); if(HO247F7_TAGS.has(k) || !genreRaw.some(g=>ho247f7Key(g)===k)) pushUnique(tags,v); });
  return { genres:genres.slice(0,5), tags:tags.slice(0,6) };
}
function ho247f7GenreTagHtml(game){
  const {genres,tags}=ho247f7SplitGenreTags(game);
  const g = genres.length ? `<div class="ho247f7ChipGroup genre"><b>TÜR</b><div>${genres.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>` : '';
  const t = tags.length ? `<div class="ho247f7ChipGroup tag"><b>ETİKET</b><div>${tags.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>` : '';
  return `<div class="ho247f7ChipWrap">${g}${t}</div>`;
}
function ho247f7DlcBadge(game){
  const all = ho247f7Key([game?.title,game?.genre,game?.tags].filter(Boolean).join(' '));
  return /\bdlc\b|expansion|ek paket|sezon|season pass|the signal|the writer|lake house|night springs|phantom liberty|left behind|separate ways/.test(all) ? '<span class="ho247f7DlcBadge">DLC</span>' : '';
}
function ho247f7Score(game){
  const v = game?.score;
  if(v === 0 || v){ const n=Number(v); if(Number.isFinite(n) && n>0) return String(Number(n.toFixed(1))).replace('.0',''); }
  return 'Puan yok';
}
function ho247f7SeriesStats(items=[]){
  const total = items.reduce((s,g)=>s+Number(g.eps || seriesEpisodes(g).length || 0),0);
  const watched = items.reduce((s,g)=>s+Number(g.watchedEps || 0),0);
  const scores = items.map(g=>Number(g.score||0)).filter(n=>Number.isFinite(n)&&n>0);
  const avg = scores.length ? String(Number((scores.reduce((a,b)=>a+b,0)/scores.length).toFixed(1))).replace('.0','') : 'Puan yok';
  const percent = total ? Math.round(watched/Math.max(1,total)*100) : 0;
  return {total, watched, avg, percent:Math.max(0,Math.min(100,percent))};
}
function ho247f7SeriesMiniList(items=[]){
  const rows = items.slice().sort((a,b)=>Number(a.seriesOrder||9999)-Number(b.seriesOrder||9999)||String(a.title||'').localeCompare(String(b.title||''),'tr'));
  return `<div class="ho247f7SeriesMini"><div class="ho247f7SeriesMiniHead"><b>Serideki Oyunlar</b><span>${rows.length} oyun</span></div><div class="ho247f7SeriesMiniScroll">${rows.map((g,i)=>`<button type="button" class="ho247f7SeriesMiniRow" data-watch-series="${esc(g.id)}"><img src="${esc(coverFor(g))}" alt="${esc(g.title)}" onerror="this.src='/assets/hayatimiz-kapak.png'"><div><b>${esc(g.title)}</b><small>Sıra ${esc(g.seriesOrder || i+1)} • ${Number(g.watchedEps||0)}/${Number(g.eps||seriesEpisodes(g).length||0)} bölüm</small></div>${ho247f7DlcBadge(g)}</button>`).join('')}</div></div>`;
}
