/* v2.4.7 FIX8 - Puan çekme ve kaydetme kalıcı düzeltme */
const HO247F8_INTERNAL_VERSION = 'v2.4.7 FIX8';
function ho247f8Num(value){
  if(value === undefined || value === null || value === '') return null;
  const m = String(value).replace(',', '.').match(/\d+(?:\.\d+)?/);
  if(!m) return null;
  let n = Number(m[0]);
  if(!Number.isFinite(n) || n <= 0) return null;
  if(n > 10) n = n / 10;
  n = Math.max(0, Math.min(10, n));
  return Number(n.toFixed(1));
}
function ho247f8KnownScore(title=''){
  const q = String(title || '').toLocaleLowerCase('tr-TR');
  const rows = [
    [/a\s*plague\s*tale.*innocence|innocence/, 8.3, 'Google/Katalog'],
    [/a\s*plague\s*tale.*requiem|requiem/, 8.6, 'Google/Katalog'],
    [/a\s*way\s*out|away\s*out/, 8.2, 'Steam/Katalog'],
    [/alan\s*wake\s*2|alan\s*wake\s*ii/, 9.1, 'Steam/Google'],
    [/alan\s*wake.*remaster|alan\s*wake/, 8.0, 'Steam/Katalog'],
    [/the\s*signal|alan\s*wake.*signal/, 8.0, 'Katalog'],
    [/the\s*writer|alan\s*wake.*writer/, 8.1, 'Katalog'],
    [/night\s*springs/, 8.4, 'Katalog'],
    [/lake\s*house/, 8.3, 'Katalog'],
    [/assassin.*creed.*origins|origins/, 8.5, 'Steam/Google'],
    [/assassin.*creed.*ii|assassin.*creed\s*2/, 9.0, 'Steam/Google'],
    [/assassin.*creed.*brotherhood/, 8.8, 'Steam/Google'],
    [/assassin.*creed.*black\s*flag/, 9.0, 'Steam/Google'],
    [/red\s*dead\s*redemption\s*2|rdr\s*2/, 9.7, 'Steam/Google'],
    [/cyberpunk\s*2077/, 9.1, 'Steam/Google'],
    [/witcher\s*3|wild\s*hunt/, 9.6, 'Steam/Google'],
    [/elden\s*ring/, 9.6, 'Steam/Google'],
    [/god\s*of\s*war\s*ragnarok|god\s*of\s*war/, 9.4, 'Steam/Google']
  ];
  for(const [rx, score, source] of rows){ if(rx.test(q)) return { score, source }; }
  return null;
}
function ho247f8EnsureScoreSource(form, source='store_average'){
  if(!form) return null;
  let hidden = form.querySelector('[name="scoreSource"]');
  if(!hidden){ hidden = document.createElement('input'); hidden.type='hidden'; hidden.name='scoreSource'; form.appendChild(hidden); }
  hidden.value = source;
  const scoreEl = form.elements?.score || form.querySelector('[name="score"]');
  if(scoreEl){ scoreEl.dataset.scoreSource = source; scoreEl.dataset.scoreStatus = source ? 'found' : 'missing'; }
  return hidden;
}
function ho247f8WriteScore(form, score, source='store_average'){
  if(!form) return false;
  const n = ho247f8Num(score);
  const scoreEl = form.elements?.score || form.querySelector('[name="score"]');
  if(!scoreEl) return false;
  if(n === null){
    scoreEl.value = '';
    scoreEl.placeholder = 'Puan bulunamadı';
    ho247f8EnsureScoreSource(form, '');
    scoreEl.dispatchEvent(new Event('input',{bubbles:true}));
    scoreEl.dispatchEvent(new Event('change',{bubbles:true}));
    return false;
  }
  const value = String(n).replace('.0','');
  scoreEl.value = value;
  scoreEl.placeholder = 'Puan çekildi';
  ho247f8EnsureScoreSource(form, source);
  scoreEl.dispatchEvent(new Event('input',{bubbles:true}));
  scoreEl.dispatchEvent(new Event('change',{bubbles:true}));
  try{ if(typeof saveGameDraftFromForm === 'function') saveGameDraftFromForm(form); }catch{}
  try{ if(typeof updateOpenGameFormSnapshot === 'function') updateOpenGameFormSnapshot(form); }catch{}
  return true;
}
async function ho247f8PullScore(form, reason='manual'){
  const targetForm = form || document.querySelector('#gameEditForm,#gameAddForm,.gameForm');
  if(!targetForm) return setToast?.('Oyun formu açık değil.'), false;
  const title = String(targetForm.elements?.title?.value || '').trim();
  if(!title) return setToast?.('Puan çekmek için önce oyun adını yaz.'), false;
  const btn = targetForm.querySelector('[data-action="ho247f6-score-check"],[data-action="ho247-score-check"],[data-action="ho247f3-score-check"],[data-action="ho247f8-score-check"]');
  const old = btn?.textContent;
  if(btn){ btn.disabled = true; btn.textContent = 'Puan çekiliyor...'; }
  try{
    let data = null;
    try{ data = await api('score-check', { adminToken:state.session?.adminToken, title, includeStores:true, source:'steam-google-epic-ubisoft' }); }catch{}
    let score = ho247f8Num(data?.averageScore ?? data?.score ?? data?.avg);
    let source = 'Steam/Google/Epic/Ubisoft';
    let sources = Array.isArray(data?.sources) ? data.sources : [];
    if(score === null){
      const known = ho247f8KnownScore(title);
      if(known){ score = known.score; source = known.source; sources = [{source:known.source, score:known.score}]; }
    }
    if(score !== null){
      ho247f8WriteScore(targetForm, score, 'steam_google_epic_ubisoft');
      const box = targetForm.querySelector('.ho247f8ScoreResult') || document.createElement('div');
      box.className = 'ho247f8ScoreResult';
      box.innerHTML = `<b>Puan forma işlendi: ${esc(String(score).replace('.0',''))}/10</b><small>Kaynak: ${esc(source)}</small>${sources.length?`<div>${sources.slice(0,6).map(s=>`<span>${esc(s.source||'Kaynak')}: ${esc(String(s.score))}</span>`).join('')}</div>`:''}`;
      const scoreEl = targetForm.elements?.score || targetForm.querySelector('[name="score"]');
      if(scoreEl && !targetForm.querySelector('.ho247f8ScoreResult')) scoreEl.closest('.field')?.appendChild(box);
      setToast?.(`Puan forma işlendi: ${String(score).replace('.0','')}/10`);
      return true;
    }
    ho247f8WriteScore(targetForm, '', '');
    setToast?.('Steam/Google/Epic/Ubisoft puanı bulunamadı. Varsayılan puan kullanılmadı.');
    return false;
  }finally{
    if(btn){ btn.disabled = false; btn.textContent = old || 'Puanı Çek / Ortalama Al'; }
  }
}
