    if(scoreEl){ scoreEl.value=''; scoreEl.placeholder='Puan bulunamadı'; scoreEl.dispatchEvent(new Event('input',{bubbles:true})); }
    ho247f10Notify('Puan bulunamadı. Varsayılan puan yazılmadı.', 'warn'); return false;
