function ho247f10MergeMeta(game, meta={}, scoreData={}){
  const m=meta.meta||meta||{}; const scoreRaw=scoreData.score||scoreData.averageScore||m.score; const score=Number(String(scoreRaw||'').replace(',','.'));
  const patch={...game};
  const set=(key,val)=>{ if(val!==undefined&&val!==null&&String(val).trim()) patch[key]=String(val).trim(); };
  set('cover', m.cover || (Array.isArray(meta.candidates)&&meta.candidates.find(c=>c.cover)?.cover));
  set('releaseDate', m.releaseDate || m.released);
  set('genre', m.genre);
  set('tags', m.tags || game.tags);
  set('seriesName', m.seriesName || m.series_name);
  set('description', m.description || m.story || game.description);
  if(Number.isFinite(score)&&score>0) patch.score=Number((score>10?score/10:score).toFixed(1));
  patch.episodes=Array.isArray(game.episodes)?game.episodes:[];
  return patch;
}
async function ho247f10BulkRefreshAll(){
  const games=Array.isArray(state.games)?state.games:[]; if(!games.length) return ho247f10Notify('Kayıtlı oyun yok.', 'warn');
  if(!confirm(`${games.length} mevcut oyun için kapak/tarih/tür/etiket/açıklama/puan tekrar çekilip güncellensin mi? Boş gelen veri mevcut alanı silmez.`)) return;
  let ok=0, fail=0;
  ho247f10Notify('Tüm mevcut oyunlar tekrar çekiliyor...', 'ok');
  for(const game of games){
    try{
      const title=String(game.title||'').trim();
      const meta=await api('game-meta',{adminToken:state.session?.adminToken,title}).catch(()=>({}));
      const score=await api('score-check',{adminToken:state.session?.adminToken,title}).catch(()=>({}));
      const patch=ho247f10MergeMeta(game,meta,score);
      const res=await api('games-update',{adminToken:state.session?.adminToken,gameId:game.id,game:patch});
      const saved=res?.game?mapGame(res.game):patch;
      state.games=state.games.map(g=>String(g.id)===String(game.id)?saved:g);
      ok++;
      ho247f10Notify(`${title} güncellendi (${ok}/${games.length})`, 'ok');
    }catch(error){ fail++; console.warn('FIX10 toplu oyun güncelleme hatası:', game?.title, error); }
  }
  render?.();
  ho247f10Notify(`Toplu güncelleme tamamlandı: ${ok} başarılı, ${fail} hata.`, fail?'warn':'ok');
}
