/* v2.4.7 FIX11 - Videolara alfabetik şerit ve tüm mevcut oyunları tekrar çek */
const HO247F11_INTERNAL_VERSION = 'v2.4.7 FIX11';
function ho247f11Initial(value=''){
  const raw=String(value||'').trim();
  if(!raw) return '#';
  const first=raw[0].toLocaleUpperCase('tr-TR');
  return /[0-9]/.test(first) ? '0-9' : first;
}
function ho247f11GroupRows(rows=[]){
  const map=new Map();
  rows.forEach(row=>{
    const key=ho247f11Initial(row?.g?.title||row?.ep?.title||'');
    if(!map.has(key)) map.set(key,[]);
    map.get(key).push(row);
  });
  const order=['0-9','A','B','C','Ç','D','E','F','G','Ğ','H','I','İ','J','K','L','M','N','O','Ö','P','R','S','Ş','T','U','Ü','V','Y','Z','#'];
  return order.filter(k=>map.has(k)).map(k=>({letter:k,items:map.get(k).sort((a,b)=>String(a.g?.title||'').localeCompare(String(b.g?.title||''),'tr') || Number(a.ep?.number||0)-Number(b.ep?.number||0))}));
}
function ho247f11VideoCard(row){
  const g=row.g||{}, ep=row.ep||{}, index=Number(row.index||0);
  if(typeof ho247f10VideoCard==='function') return ho247f10VideoCard(g,ep,index);
  const cover=(typeof ho247f10Cover==='function'?ho247f10Cover(g,ep):(ep.thumbnail||g.cover||'/assets/hayatimiz-kapak.png'));
  const meta=(typeof ho247f10MetaHtml==='function'?ho247f10MetaHtml(g):(typeof ho247GenreTags==='function'?ho247GenreTags(g):''));
  const dlc=(typeof ho247f10Dlc==='function'?ho247f10Dlc(g):(typeof ho247DlcBadge==='function'?ho247DlcBadge(g):''));
  return `<article class="ho247f10VideoCard ho247f11VideoCard"><button class="ho240f60CardClick" data-watch-series="${esc(g.id)}" data-watch-series-episode="${esc(String(index))}" aria-label="${esc(g.title)} videosunu aç"></button><div class="ho247f10VideoCover ho247f11VideoCover"><img src="${esc(cover)}" alt="${esc(g.title)}" onerror="this.src='/assets/hayatimiz-kapak.png'">${dlc}<span>${esc(String(ep.number||index+1))}. Bölüm</span></div><div class="ho247f10VideoBody"><h3 title="${esc(g.title)}">${esc(g.title)}</h3><p title="${esc(ep.title||'')}">${esc(String(ep.title||'Bölüm').slice(0,95))}</p>${meta}<div class="rowActions"><button class="miniBtn primary" data-watch-series="${esc(g.id)}" data-watch-series-episode="${esc(String(index))}">İzle</button>${ep.videoUrl?`<a class="miniBtn" target="_blank" rel="noopener" href="${esc(ep.videoUrl)}">YouTube</a>`:''}</div></div></article>`;
}
function ho247f11VideosPage(){
  const rows=(typeof ho247f10VideoRows==='function'?ho247f10VideoRows():(typeof ho247AllVideoRows==='function'?ho247AllVideoRows():[]));
  const groups=ho247f11GroupRows(rows);
  const nav=groups.length?`<div class="ho247f11VideoAlphabet"><b>Harf Şeridi</b>${groups.map(g=>`<a href="#video-${esc(routeSlug(g.letter))}">${esc(g.letter)}</a>`).join('')}</div>`:'';
  return `<section class="ho247f10VideosPage ho247f11VideosPage"><div class="ho247f10Hero ho247f11Hero"><div><span class="eyebrow">Profesyonel Video Arşivi</span><h1>Videolar</h1><p>Videolar artık alfabetik harf şeritleriyle A serisi, B serisi gibi gruplara ayrılır. Kapaklar taşmadan tam sığar.</p></div><span class="pill green">${rows.length} video</span></div>${nav}<div class="ho247f11VideoSections">${groups.map(group=>`<section class="ho247f11VideoLetter" id="video-${esc(routeSlug(group.letter))}"><div class="ho247f11LetterHead"><h2>${esc(group.letter)} Harfi</h2><span>${group.items.length} video</span></div><div class="ho247f10VideoGrid ho247f11VideoGrid">${group.items.map(ho247f11VideoCard).join('')}</div></section>`).join('') || '<section class="card wide"><h2>Video bulunamadı</h2><p class="muted">Oyun düzenle ekranından YouTube senkronize et.</p></section>'}</div></section>`;
}
async function ho247f11MetaForGame(game){
  const title=String(game?.title||'').trim();
  const out={...game};
  const keep=(key,val)=>{ if(val!==undefined&&val!==null&&String(val).trim()) out[key]=String(val).trim(); };
  let meta={}, score={};
  try{ meta=await api('game-meta',{adminToken:state.session?.adminToken,title}); }catch(err){ console.warn('FIX11 game-meta hata:', title, err); }
  try{ score=await api('score-check',{adminToken:state.session?.adminToken,title}); }catch(err){ console.warn('FIX11 score-check hata:', title, err); }
  const m=meta?.meta||meta||{};
  const cand=Array.isArray(meta?.candidates)?meta.candidates:[];
  keep('cover', m.cover || cand.find(c=>c.cover)?.cover);
  keep('releaseDate', m.releaseDate || m.released || cand.find(c=>c.releaseDate||c.released)?.releaseDate || cand.find(c=>c.releaseDate||c.released)?.released);
  keep('genre', m.genre || cand.find(c=>c.genre)?.genre);
  keep('tags', m.tags || out.tags);
  keep('seriesName', m.seriesName || m.series_name || out.seriesName);
  keep('description', m.description || m.story || m.summary || out.description);
  const raw=score?.score||score?.averageScore||score?.avg||m.score;
  const n=Number(String(raw||'').replace(',','.'));
  if(Number.isFinite(n)&&n>0) out.score=Number((n>10?n/10:n).toFixed(1));
  return out;
}
async function ho247f11BulkRefetchAll(){
  const games=Array.isArray(state.games)?state.games:[];
  if(!games.length){ (typeof setToast==='function'?setToast('Kayıtlı oyun yok.'):alert('Kayıtlı oyun yok.')); return; }
  if(!confirm(`${games.length} kayıtlı oyun için tüm bilgileri tekrar çekip güncelleyelim mi? Boş gelen veri mevcut alanı silmez.`)) return;
  let ok=0, fail=0;
  try{ setToast?.('Tüm kayıtlı oyunlar tekrar çekiliyor...'); }catch{}
  for(const game of games){
    try{
      const patch=await ho247f11MetaForGame(game);
      const res=await api('games-update',{adminToken:state.session?.adminToken,gameId:game.id,game:patch});
      const saved=res?.game?(typeof mapGame==='function'?mapGame(res.game):res.game):patch;
      state.games=state.games.map(g=>String(g.id)===String(game.id)?saved:g);
      ok++;
      try{ setToast?.(`${game.title} tekrar çekildi ve güncellendi (${ok}/${games.length})`); }catch{}
    }catch(error){
      fail++;
      console.warn('FIX11 tümünü getir hata:', game?.title, error);
    }
  }
  try{ render?.(); }catch{}
  const msg=`Tümünü getir tamamlandı: ${ok} oyun güncellendi${fail?`, ${fail} hata`:''}.`;
  try{ setToast?.(msg); }catch{ alert(msg); }
}
