  if(!tags.length && genres.length){ tags=[]; }
  // tags alanına yanlışlıkla tür karıştıysa ayır, ama mevcut veriyi silme.
  const tagOnly=tags.filter(t=>!typeWords.has(t.toLocaleLowerCase('tr-TR')));
  const genreExtra=tags.filter(t=>typeWords.has(t.toLocaleLowerCase('tr-TR')));
  genres=[...new Set([...genres,...genreExtra])];
  tags=[...new Set(tagOnly)];
  const gHtml=genres.length?`<div class="ho247f13MetaGroup type"><b>TÜR</b><div>${genres.map(x=>`<span>${ho247f13Esc(x)}</span>`).join('')}</div></div>`:'';
