/* v2.4.9 FIX1 - Profesyonel harf filtresi, canlı kapak, YouTube tablo ve schema versiyon düzeltmesi */
const HO249F1_VERSION = 'v2.4.9 FIX1';

function ho249f1Esc(value){
  try{ return typeof esc === 'function' ? esc(value) : String(value ?? '').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
  catch{ return String(value ?? ''); }
}
function ho249f1Text(value){ return String(value || '').trim(); }
function ho249f1Norm(value){
  return String(value || '')
    .toLocaleLowerCase('tr-TR')
    .replace(/[^a-z0-9ığüşöçİĞÜŞÖÇ\s:.-]/gi,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function ho249f1Initial(title=''){
  const t=String(title||'').trim().toLocaleUpperCase('tr-TR');
  if(!t) return '#';
  const first=t[0];
  return /[0-9]/.test(first) ? '0-9' : first;
}
function ho249f1Letters(items=[], getter=(x)=>x.title){
  const order=['0-9','A','B','C','Ç','D','E','F','G','Ğ','H','I','İ','J','K','L','M','N','O','Ö','P','R','S','Ş','T','U','Ü','V','Y','Z'];
  const set=new Set(items.map(x=>ho249f1Initial(getter(x))).filter(Boolean));
  return order.filter(l=>set.has(l)).concat([...set].filter(l=>!order.includes(l)).sort((a,b)=>a.localeCompare(b,'tr')));
}
function ho249f1LetterRail(items=[], active='', type='video', getter=(x)=>x.title){
  const letters=ho249f1Letters(items,getter);
  if(!letters.length) return '';
  return `<section class="ho249f1LetterPanel" data-ho249f1-type="${ho249f1Esc(type)}">
    <div class="ho249f1LetterInfo">
      <b>Harfe Göre Gezin</b>
      <span>${type==='series'?'Serileri':'Videoları'} alfabetik gruplara ayırır; sayfadan çıkmadan ilgili harfe gider.</span>
    </div>
    <div class="ho249f1LetterChips">
      ${letters.map(l=>`<button type="button" class="${active===l?'active':''}" data-ho249f1-letter="${ho249f1Esc(l)}" data-ho249f1-type="${ho249f1Esc(type)}">${ho249f1Esc(l)}</button>`).join('')}
    </div>
  </section>`;
}
function ho249f1GroupByLetter(items=[], getter=(x)=>x.title){
  const map=new Map();
  items.forEach(item=>{
    const l=ho249f1Initial(getter(item));
    if(!map.has(l)) map.set(l,[]);
    map.get(l).push(item);
  });
  return ho249f1Letters(items,getter).map(letter=>({letter,items:(map.get(letter)||[]).sort((a,b)=>String(getter(a)||'').localeCompare(String(getter(b)||''),'tr'))}));
}
function ho249f1SplitTokens(value=''){
  return String(value||'')
    .split(',')
    .map(x=>x.trim())
    .filter(Boolean)
    .filter((v,i,a)=>a.findIndex(x=>x.toLocaleLowerCase('tr-TR')===v.toLocaleLowerCase('tr-TR'))===i);
}
const HO249F1_GENRE_WORDS = ['Aksiyon','Macera','Aksiyon-macera','RPG','Korku','Hayatta Kalma Korku','Psikolojik Gerilim','Gizlilik','Açık Dünya','FPS','TPS','Platform','Bulmaca','Yarış','Spor','Strateji','Simülasyon','Bağımsız Yapımcı','Hikaye Odaklı'];
function ho249f1GenreTagsHtml(g){
  const rawGenre=ho249f1SplitTokens(g?.genre||'');
  const rawTags=ho249f1SplitTokens(g?.tags||'');
  const genreSet=new Set(HO249F1_GENRE_WORDS.map(x=>x.toLocaleLowerCase('tr-TR')));
  const genres=[...rawGenre, ...rawTags.filter(t=>genreSet.has(t.toLocaleLowerCase('tr-TR')))].filter((v,i,a)=>a.findIndex(x=>x.toLocaleLowerCase('tr-TR')===v.toLocaleLowerCase('tr-TR'))===i);
  const tags=rawTags.filter(t=>!genreSet.has(t.toLocaleLowerCase('tr-TR')));
  return `<div class="ho249f1Taxonomy"><div><span>TÜR</span><div>${(genres.length?genres:['Genel']).map(t=>`<em class="genre">${ho249f1Esc(t)}</em>`).join('')}</div></div><div><span>ETİKET</span><div>${(tags.length?tags:['Etiket yok']).map(t=>`<em class="tag">${ho249f1Esc(t)}</em>`).join('')}</div></div></div>`;
}
function ho249f1DlcBadge(g){
  try{
    if(typeof ho246fix7IsDlcGame==='function' && ho246fix7IsDlcGame(g)) return '<span class="ho249f1Dlc">DLC</span>';
  }catch{}
  const text=ho249f1Norm([g?.title,g?.genre,g?.tags].join(' '));
  return /\bdlc\b|expansion|episode|the writer|the signal|lake house|night springs|phantom liberty|blood and wine|hearts of stone|left behind|secrets of the spires/.test(text) ? '<span class="ho249f1Dlc">DLC</span>' : '';
}
function ho249f1Cover(g){ try{ return coverFor(g); }catch{ return g?.cover || '/assets/hayatimiz-kapak.png'; } }
function ho249f1EpisodeRowsFromGames(games=[]){
  const rows=[];
  games.forEach(g=>{
    const eps = typeof normalizeEpisodes==='function' ? normalizeEpisodes(g.episodes) : [];
    if(eps.length){
      eps.forEach((ep,i)=>rows.push({game:g, ep:{...ep, number:ep.number||i+1}}));
    }else{
      rows.push({game:g, ep:{number:Number(g.watchedEps||0)+1, title:g.title, thumbnail:g.cover, videoUrl:g.videoUrl || g.playlistUrl || ''}});
    }
  });
  return rows;
}
function ho249f1VideoCard(row){
  const g=row.game || row;
  const ep=row.ep || {};
  const cover=ep.thumbnail || g.cover || ho249f1Cover(g);
  const title=String(g.title||'Oyun');
  const epTitle=String(ep.title||`${ep.number||1}. Video`);
  const target=ep.videoUrl || g.videoUrl || g.playlistUrl || '';
  return `<article class="ho249f1VideoCard">
    <div class="ho249f1VideoCover">
      <img src="${ho249f1Esc(cover)}" alt="${ho249f1Esc(title)}" onerror="this.src='/assets/hayatimiz-kapak.png'">
      ${ho249f1DlcBadge(g)}
      <span class="ho249f1VideoNo">${ho249f1Esc(ep.number||'')}</span>
    </div>
    <div class="ho249f1VideoBody">
      <h3>${ho249f1Esc(title)}</h3>
      <p>${ho249f1Esc(epTitle).slice(0,140)}${epTitle.length>140?'...':''}</p>
      ${ho249f1GenreTagsHtml(g)}
      <div class="ho249f1VideoActions">
        ${target?`<button class="miniBtn primary" data-open-url="${ho249f1Esc(target)}">İzle</button>`:'<button class="miniBtn disabled" disabled>Link yok</button>'}
        <span>YouTube</span>
      </div>
    </div>
  </article>`;
}
