/* v2.4.9 FIX8 - Kapak galerisi temizle + RAWG oyunlarını çek */
const HO249F8_VERSION = 'v2.4.9 FIX8';

function ho249f8Esc(value){
  try { return typeof esc === 'function' ? esc(value) : String(value ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
  catch { return String(value ?? ''); }
}
function ho249f8Text(value){ return String(value || '').trim(); }
function ho249f8Form(){
  return document.getElementById(state?.editingGameId ? 'gameEditForm' : 'gameAddForm')
    || document.querySelector('#gameEditForm,#gameAddForm,.gameForm,.fix6GameForm,form');
}
function ho249f8Title(form){
  return ho249f8Text(form?.elements?.title?.value || form?.querySelector?.('[name="title"]')?.value);
}
function ho249f8CoverOf(item={}){
  return ho249f8Text(item.cover || item.cover_url || item.background_image || item.image || item.header_image || item.thumbnail || item.capsule || item.poster);
}
function ho249f8TitleOf(item={}){
  return ho249f8Text(item.title || item.name || item.gameTitle || item.label);
}
function ho249f8Norm(value){
  return String(value || '').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9ığüşöçİĞÜŞÖÇ\s:.-]/gi,' ').replace(/\s+/g,' ').trim();
}
function ho249f8Score(query, item={}){
  const q = ho249f8Norm(query);
  const t = ho249f8Norm(ho249f8TitleOf(item));
  let s = 0;
  if(q && t && q === t) s += 140;
  if(q && t && (t.includes(q) || q.includes(t))) s += 80;
  q.split(' ').filter(w=>w.length>2).forEach(w=>{ if(t.includes(w)) s += 14; });
  const all = ho249f8Norm([t,item.source,item.type,item.description,item.summary].join(' '));
  const isDlc = /\bdlc\b|expansion|episode|the writer|the signal|lake house|night springs|phantom liberty|blood and wine|hearts of stone|left behind|secrets of the spires/.test(q);
  if(isDlc){
    ['dlc','expansion','episode','writer','signal','lake house','night springs','phantom liberty','blood and wine','hearts of stone','left behind','secrets of the spires'].forEach(w=>{
      if(q.includes(w) && all.includes(w)) s += 32;
    });
  }else if(/\bdlc\b|expansion|episode/.test(all)){
    s -= 25;
  }
  if(String(item.source||'').toLowerCase().includes('rawg')) s += 20;
  if(String(item.source||'').toLowerCase().includes('steam')) s += 6;
  return s;
}
function ho249f8Unique(query, list=[]){
  const seen = new Set();
  return list.map(item=>({
      ...item,
      cover: ho249f8CoverOf(item),
      title: ho249f8TitleOf(item) || query,
      source: item.source || 'RAWG',
      matchScore: ho249f8Score(query, item)
    }))
    .filter(item=>{
      if(!item.cover) return false;
      const key = String(item.cover).replace(/\?.*$/,'');
      if(seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a,b)=>Number(b.matchScore||0)-Number(a.matchScore||0))
    .slice(0,6);
}
function ho249f8ClearState(){
  try{
    state.ho240f11CoverCandidates = [];
    state.ho240f10CoverCandidates = [];
    state.ho249f8RawgCandidates = [];
    state.rawgCandidates = [];
    state.coverCandidates = [];
    state.ho249CoverCandidates = [];
    state.ho249f3CoverCandidates = [];
  }catch{}
}
function ho249f8ClearGallery(){
  ho249f8ClearState();
  document.querySelectorAll('.ho249f8RawgPanel,.ho249f3CoverPanel,.ho249f1CoverPanel,.ho249CoverPanel,.ho240f11CoverGallery,.ho240f10CoverGallery,.rawgCandidates,.coverCandidates,.coverGallery').forEach(el=>el.remove());
  document.querySelectorAll('.ho249f8GalleryStatus').forEach(el=>el.textContent = 'Kapak kayıtları temizlendi. Yeni sonuç için RAWG Oyunlarını Çek veya Kapakları Getir kullan.');
  setToast?.('Kapak galerisindeki tüm sonuçlar temizlendi.');
}
function ho249f8SetCover(form, cover){
  if(!form || !cover) return;
  const input = form.elements?.cover || form.querySelector('[name="cover"]');
  if(input){
    input.value = cover;
    input.dispatchEvent(new Event('input', {bubbles:true}));
    input.dispatchEvent(new Event('change', {bubbles:true}));
  }
  try{ ho249f3SyncPreview?.(form); }catch{}
  try{ ho249f4RestoreScoreIfWiped?.(form); }catch{}
  form.querySelectorAll('.coverPreview,.ho240f66CoverPreview').forEach(box=>{
    box.classList.remove('isEmpty');
    box.innerHTML = `<img src="${ho249f8Esc(cover)}" alt="Kapak önizleme">`;
  });
  form.querySelectorAll('.fix6PreviewCover img,.ho240f66LiveCard img,.ho249f3PreviewCover img').forEach(img=>{ img.src = cover; });
}
function ho249f8RenderRawg(form, candidates=[]){
  if(!form) return;
  form.querySelectorAll('.ho249f8RawgPanel').forEach(el=>el.remove());
  const panel = document.createElement('section');
  panel.className = 'ho249f8RawgPanel';
  panel.innerHTML = `<div class="ho249f8RawgHead">
    <div><b>RAWG Kapak Sonuçları</b><span>Oyun adına göre en doğru 6 kapak. Seçilen kapak sadece forma işlenir; Kaydet/Güncelle yapmadan Supabase’e yazılmaz.</span></div>
    <small>${candidates.length}/6</small>
  </div>
  <div class="ho249f8RawgGrid">
    ${candidates.map((c,i)=>`<button type="button" data-ho249f8-pick="${i}">
      <img src="${ho249f8Esc(c.cover)}" onerror="this.src='/assets/hayatimiz-kapak.png'">
      <b>${ho249f8Esc(c.title || 'Kapak')}</b>
      <span>${ho249f8Esc(c.source || 'RAWG')} • Eşleşme %${Math.max(0,Math.min(100,Math.round(c.matchScore||60)))}</span>
    </button>`).join('') || '<p>RAWG sonucu bulunamadı. Oyun adını kontrol et.</p>'}
  </div>`;
  const target = form.querySelector('.ho249f8CoverTools') || form.querySelector('[name="cover"]')?.closest?.('.field') || form.querySelector('.coverPreview')?.parentElement || form;
  target.insertAdjacentElement('afterend', panel);
  panel.querySelectorAll('[data-ho249f8-pick]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const item = candidates[Number(btn.dataset.ho249f8Pick || 0)];
      if(item?.cover){
        ho249f8SetCover(form, item.cover);
        setToast?.('RAWG kapağı canlı önizlemeye işlendi.');
      }
    });
  });
}
async function ho249f8FetchRawg(){
  const form = ho249f8Form();
  const title = ho249f8Title(form);
  if(!form || !title){
    setToast?.('RAWG kapak çekmek için önce oyun adını yaz.');
    return;
  }
  const btn = document.querySelector('[data-ho249f8-rawg]');
  const oldText = btn?.textContent;
  if(btn){ btn.disabled = true; btn.textContent = 'RAWG çekiliyor...'; }
  try{
    setToast?.('RAWG oyun kapakları çekiliyor...');
    const list = [];
    try{
      const meta = await api('game-meta', {
        adminToken: state.session?.adminToken,
        title,
        rawg: true,
        coverSearch: true,
        steam: false,
        google: false,
        epic: false,
        ubisoft: false,
        cache: false,
        limit: 6,
        version: HO249F8_VERSION
      });
      if(meta?.meta) list.push({...meta.meta, source: meta.source || 'RAWG'});
      if(Array.isArray(meta?.candidates)) list.push(...meta.candidates.map(c=>({...c, source: c.source || 'RAWG'})));
      if(Array.isArray(meta?.results)) list.push(...meta.results.map(c=>({...c, source: c.source || 'RAWG'})));
    }catch(error){ console.warn('FIX8 game-meta RAWG alınamadı:', error); }
    try{
      const rawg = await api('rawg-search', { adminToken: state.session?.adminToken, title, query: title, limit: 6, cache:false });
      if(Array.isArray(rawg?.results)) list.push(...rawg.results.map(c=>({...c, source: c.source || 'RAWG'})));
      if(Array.isArray(rawg?.candidates)) list.push(...rawg.candidates.map(c=>({...c, source: c.source || 'RAWG'})));
    }catch(error){ console.warn('FIX8 rawg-search endpoint yok veya hata:', error); }
    try{
      if(typeof ho240f42BuildCovers === 'function'){
        const more = await ho240f42BuildCovers(title);
        list.push(...more.map(c=>({...c, source: c.source || 'RAWG/Meta'})));
      }
    }catch{}
    const candidates = ho249f8Unique(title, list);
    state.ho249f8RawgCandidates = candidates;
    state.rawgCandidates = candidates;
    ho249f8RenderRawg(form, candidates);
    if(candidates[0]?.cover){
      ho249f8SetCover(form, candidates[0].cover);
      setToast?.('RAWG kapakları çekildi. En iyi kapak canlı önizlemeye işlendi.');
    }else{
      setToast?.('RAWG kapak sonucu bulunamadı.');
    }
  }finally{
    if(btn){ btn.disabled = false; btn.textContent = oldText || 'RAWG Oyunlarını Çek'; }
  }
}
function ho249f8InstallTools(){
  const form = ho249f8Form();
  if(!form || form.querySelector('.ho249f8CoverTools')) return;
  const tools = document.createElement('section');
  tools.className = 'ho249f8CoverTools';
  tools.innerHTML = `<div>
      <b>Kapak Galerisi Araçları</b>
      <span class="ho249f8GalleryStatus">Kalabalık sonuçları temizle veya RAWG’den doğru oyun kapaklarını çek.</span>
    </div>
    <div>
      <button type="button" class="miniBtn danger" data-ho249f8-clear>Tüm Kayıtları Sil</button>
      <button type="button" class="miniBtn primary" data-ho249f8-rawg>RAWG Oyunlarını Çek</button>
    </div>`;
  const target = form.querySelector('.ho249f3CoverPanel,.ho249f1CoverPanel,.ho249CoverPanel,.ho240f11CoverGallery,.coverGallery')
    || form.querySelector('[name="cover"]')?.closest?.('.field')
    || form.querySelector('.coverPreview')?.parentElement
    || form;
  target.insertAdjacentElement('beforebegin', tools);
}
try{
  document.addEventListener('click', (event)=>{
    if(event.target?.closest?.('[data-ho249f8-clear]')){
      event.preventDefault();
      event.stopPropagation();
      ho249f8ClearGallery();
      return;
    }
    if(event.target?.closest?.('[data-ho249f8-rawg]')){
      event.preventDefault();
      event.stopPropagation();
      ho249f8FetchRawg();
      return;
    }
  }, true);

  const oldRender = typeof render === 'function' ? render : null;
  if(oldRender && !window.__ho249f8RenderWrapped){
    window.__ho249f8RenderWrapped = true;
    render = function(){
      const result = oldRender.apply(this, arguments);
      setTimeout(ho249f8InstallTools, 80);
      setTimeout(ho249f8InstallTools, 300);
      return result;
    };
  }
  setInterval(ho249f8InstallTools, 1500);

  if(Array.isArray(VERSION_NOTES_ARCHIVE) && !VERSION_NOTES_ARCHIVE.some(n=>n.version===HO249F8_VERSION)){
    VERSION_NOTES_ARCHIVE.unshift({
      version: HO249F8_VERSION,
      title: 'Kapak Galerisi RAWG ve Temizleme',
      summary: 'Kapak galerisindeki sonuçları temizleme ve RAWG oyunlarını çekme butonları eklendi.',
      status: 'Tamamlandı'
    });
  }
  try{ localStorage.setItem('hayatimiz_last_fix_version', HO249F8_VERSION); }catch{}
}catch(error){
  console.warn('FIX8 kapak galerisi araçları kurulamadı:', error);
}

